/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080226-9","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"文教委員会","time":"午前１０時０２分～午後０時０３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の近隣セキュリティシステムの運用事業者変更","agenda":"の近隣セキュリティシステムの運用事業者変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"所管が異なってしまうかもしれないんですが、その場合は所管の方にお伝えしていただくというような発言ですが、今回、ソフトバンクテレコムという形なんですけれども、ほかの例えばドコモであるとかａｕであるとかというところの、採算が合うかという問題はあるかと思うんですけれども、今のシステムを開発をして、もしも将来的にソフトバンクが何か起きたときに、すぐ違うところに乗りかえられるとか。","respondent":"市川庶務課長","answer":"ただ今回、先ほど私の説明の中で、最初のステップの段階で、ＹＯＺＡＮが平成１９年度限りで撤退、それで平成２０年度からどちらの通信事業者にするかというところ、そこでは当然のことながらドコモ、ａｕを含めて通信事業者の選定を行ったわけですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっとお願いしたいんですね。そのためにも、やはり並列でもいいので、例えば来年度１年間かけて開発をお願いするとか、そのときにお金が発生するかどうかわかりませんけれども、いわゆるどこかのところもサブという形で準備をしていただいたほうが、こういう今回のようなことも回避できるのではないかなと思いますので、どうぞ伝えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"支障がないように、不安がないように父母にお知らせをして体制をとったという、そのことは当然のことでありますけれども、混乱がないということで進んでいるというふうに受け止めておりますので、ひと安心するところですけれども、改めてオプションとして、特定通話サービスと所在地確認サービスを受けている方々が、全児童数の中でどの程度の割合を占めて、こういうオプションをやっているのかということを。","respondent":"市川庶務課長","answer":"４番目のソフトバンクの携帯電話網の利用状況というんですか電波状況、これは確かに通信事業者各社とも、なるべくカバーできない地域をなくしていくということで、いろいろアンテナを増設したり、技術的にカバーをして競い合っているようです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"それと、所在地確認のオプションのところはわかりました。こういうふうに書いてあったので、別立てのオプションと、もともとのところがどういうふうに違うのかというところはちょっとわからなかったので。わざわざオプションでそんなことがあるなんていうことはあってはならないことで、これは意味がないと思ったので、改めて確認させていただきましたけれども、違いがよくわかりました。","respondent":"市川庶務課長","answer":"最後にご質問いただいた点につきましては、ちょっと私のほうで承知しておりません。","voiceIndex":10,"id":"exchange-004"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"いくつか確認したいと思うんですが、まず１ページ目の転換等々というところでご説明がありました。その場合に、学校側はいいかもしれないけれども、早期発見をする中で保育園とか幼稚園とか保健所であるとかというところの、かなり専門的な勉強をされていると思うんですが、そこの調和というんですか、そういう足並みはどういう形でしていけるものなのだろうかなというところ、それについてお聞きしたい。","respondent":"河野指導課長","answer":"来年度以降も継続して実施したいという方は、すべて予定をしているＮＰＯのほうに登録をし終えたというふうに聞いております。","voiceIndex":17,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"経過と、そして品川区の体制と来年度以降の事業のところの説明をまとめていただいて、非常によくわかりました。今現在の状況がどういうふうになっているのか、何人ぐらい通って子どもがいて、どういう体制になって実施していただけているのかというのを、ちょっと具体的な部分としてまず一つ伺っておきたいなというふうに思うんです。","respondent":"河野指導課長","answer":"送迎ですが、公立小学校の場合には、これは通常学級、それからこういう特別支援学級も含めて、登下校につきましては各ご家庭の責任で行うですので、現状としては、特に登下校のための便宜ということについては、私どものほうも考えておりません。","voiceIndex":19,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"通級は３校でしたので、最初の発言を訂正しておきたいと思います。その辺の状況のつかみぐあいは教育委員会としてはどういうふうになっているのか。通わせたいけれどもそういう体制をとるのは非常に困難だから通わせることができないという状況の子どもがどの程度いるというふうに認識しているのか、ちょっとそこをまず伺いたいというふうに思います。","respondent":"河野指導課長","answer":"通級に通っている子どもの保護者の方から、登下校に関する送迎の要望というようなことについては、私たちのほうに入っておりません。","voiceIndex":21,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"それと、雇用のところは、いままでは先ほど人件費が１億円かかっているという説明がありましたけれども、しかし１年契約という形であったというふうに聞いていますので、それがＮＰＯになると１年契約ではなくて、一定程度の意思があれば継続されていくのかなというふうに思って聞いていたんですけれども、その辺については、ちょっとどうなのかを改めて教えていただきたいと思います。","respondent":"河野指導課長","answer":"いままで年間契約というふうな委員のご発言でしたけれども、年間契約ではなくて６カ月を限度に契約をしていく、こういう形です。それが、今回このＮＰＯになることによって、継続雇用が可能になるです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"子どもにとって、信頼をかちとれている介助員、そういう方々がＮＰＯに登録をしたにしても、そういう形を通して、一人の子どもから見たときに同じ介助員が来年度以降も継続して当たってもらえるのかという点について質問しているつもりですけれども、ご答弁をお願いします。","respondent":"河野指導課長","answer":"できるだけそういうような形で配慮したいと思いますが、その方があくまでも、どういう形でＮＰＯに参加しているのかということにもよりますので、継続して、年度を超えてやっていただける方については、できるだけそういう配慮をしていきたいというふうに思います。","voiceIndex":25,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことであってはならないというふうに思いますので、これだけの体制がきちんと整備されてきている、そしてすべての子どもを発達させていくという角度で取り組まれているというところをやはりきちんとさせていくためにも、効果をしっかりあげるために必要な支援というのを、これからもさらに積極的に教育委員会として進めていただきたいということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-010"},{"speaker":"金野委員","kind":"確認","question":"それを１点、確認をさせてください。２点目に、私立幼稚園との連携というところで、先ほど西本委員からも質問があったのとダブるかと思うんですが、その連携で、私立幼稚園では幼稚園指導要領が、たしか終わったあとに就学するに当たって、特記事項のある子に対しては、その要領を小学校に連携をするというのがあったと記憶しているんですけれども、そういうので連携をとれる方法はないんでしょうか。","respondent":"河野指導課長","answer":"３点目の先ほどの教員の研修でございましたが、今日、私は３０分かけて特別支援教育の概要と区の取り組み状況までお話をさせていただきました。","voiceIndex":28,"id":"exchange-011"},{"speaker":"市川委員","kind":"質問・要望","question":"二つお聞きしたいんですけれども、一つは、１ページ目の特別支援教育の対象が、東京都で数字が出されているんですけれども、品川区の場合の数字を教えていただきたいとうことです。","respondent":"河野指導課長","answer":"品川区の実態というご質問ですが、現在品川区には小学生、中学生、公立の学校に通っている子どもですが、およそ１万６,０００人ぐらいかというふうに私のほうで認識しております。そのうち、いわゆる固定級に通学されているお子さんが小学生で６６名、中学生で３３名です。","voiceIndex":30,"id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点確認をさせていただきたいのですが、やはり先ほどからもずっと話を聞いていて、一番適切というか、早期に発見するのが一番いいというお話があった中で、以前、視察に行った際に、「発達障害者とは何か」みたいな、パンフレットが保護者用とたしか教師用があったと思うんですが、そういったのが品川区の中で、そういったわかりやすい、発達障害者とは何かというのを保護者が理解して。","respondent":"河野指導課長","answer":"保護者に対する啓発ですが、これは先ほども申し上げたように、これは単に学校だけの問題だけではありませんので、学校の中でカバーできる部分については積極的に学校から保護者のほうに発信する。","voiceIndex":32,"id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひ保護者に啓発等は、一番初めに見て、大きい冊子だと、なかなか皆さん、目を通すのが億劫になってしまうのかなということで、ぜひわかりやすいものをつくっていただき、そして啓発活動をより活発にしていただければなと。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"金野委員","kind":"質問","question":"すみません、今の石田慎吾委員に関連してのところなんですが、一つ教えてください。このＩＴシステム化の今説明を伺ったんですが、そうなると、このカルテ化をしていくとなると個人情報というところでは大丈夫なんでしょうか。そういうシステムを使うということはすごくいいとは思うんですが、どうなんでしょうか。","respondent":"河野指導課長","answer":"それから基本的にはどういう取り組みをしてやっていくのかということについては、保護者と連絡をとりながらやっていく、保護者の確認をとりながらやっていくというのがやはり大原則ですので、個人個人に介助員、あるいは学習支援員を配置する、措置するという場合には。","voiceIndex":35,"id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"それをＩＴ化にすることは学校には偽装請負を防止するという、今の個人情報の関係もありましたけれども、偽装請負を予防することで、こちらの右のほうを見ると、指示をメールでＮＰＯを経由してメンバーに伝える仕組みは日本で初めての試みだと、こういうことなんですけれども、今日、例えば国語なら国語の授業で、Ａさんという子どもにこういう指導、こういうかかわりをして。","respondent":"河野指導課長","answer":"要するに支援員、あるいは介助員に対する指示事項については、例えば朝、当該の児童が登校してきたときに、こういうところがぐあいが悪い、それに対して具体的に予定していた支援内容を急激に変更しなければならないというようなケースについて。","voiceIndex":37,"id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"それはわかったんですけれども、それで通じるというか、こなしていければそれはそれでいいんですけれども、そうでない場合は大いにあり得るわけですから、そこがどういうふうになってくるのかなというのが非常に心配で、私は固定した介助員が、ずっと決まった信頼関係のとれた大人として自分のところに来てもらって、学校で授業を受けるのにいてくれるという。","respondent":"河野指導課長","answer":"ちょっと私も認識が甘い部分があって、緊急の場合には事後承諾でオーケーということだそうです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"事後承諾オーケーだという、そこのところのことですけれども、どこでそういうふうになっているのか、ちょっと定かではなくて説明がないのでわからないんですけれども、公的にはこういうケースの場合は事後承諾でオーケーだという、そういうことなんですか。","respondent":"河野指導課長","answer":"そういう具体的な内容については、委託の際の仕様に基づいて行うということで、あらかじめそういう旨を盛り込んだ仕様というふうになっておりますので、可能であるです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどのパンフレットの件なんですけれども、せっかく視察に行って非常に参考になったので、ぜひ品川区でもつくっていただきたいという希望があるものですから、次長も一緒に行かれていますので、見ていただいて、どこが中心になるかわからないですけれども、あれは結構全体を網羅している部分がありますので、そこを何とか教育委員会発信で、全体的につくるとか、ちょっと考えていただきたいなと思います。","respondent":"河野指導課長","answer":"その件については、これは教育だけの問題ではなくて、児童課、保育課のほうも関与してまいりますし、さまざまな部署が絡んでまいりますので、連携をしながら検討してまいりたいというふうに考えております。","voiceIndex":44,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"事前に言っていなかったので悪かったんですけれども、地域の方から聞いた話なので確認したいと思います。非常に当初の約束と違うんだけれどもということで、親たち、聞いた方たちは、なんだというふうにちょっと不満を感じたという、そういう話を聞いたんですけれども、その辺の状況がどうなのか、事実なのかどうか、そこを確認したいと思います。","respondent":"古里学務課長","answer":"一つ、部活のあり方として、近隣の学校、それから自分の学校も含めて、活動の範囲をあまり広げることなくできる方策、こちらのほうを検討することが重要かということで、今その方向で検討しています。","voiceIndex":58,"id":"exchange-020"},{"speaker":"南委員","kind":"確認","question":"あまり長くやるつもりはありませんが、近隣の学校でできるように検討をしていきたいという、そういうことで今説明されたのかなというふうに感じたんですけれども、それでいいのかどうかの確認と、そこについては保護者の方々にそういう方向で検討しているということは同時に知らせているんでしょうか。","respondent":"長田教育次長","answer":"それに向け、検討はしてまいりましたけれども、要望はありましたけれども、この場で教育委員会としてはっきりそれを確保しますというようなことではないというふうに私どもは理解をしています。","voiceIndex":60,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"その件は、ほかのときでもいいんですが、また改めてよく調べてから質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4628#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":34630,"voices":66}},{"id":"h20-20080226-5","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"総務委員会","time":"午前１０時０２分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"最後の５ページのところを聞きたいんですけれども、都区間の合意に至らなかったというお話が最後にありましたけれども、平成１９年度のときに激変緩和措置の問題ですとか、幾つか東京都が挙げて５％にするんだということだったんですけれども、その辺のどういうところで合意に至らなかったというところの協議の中身というものをお聞かせ願えないかなと思います。","respondent":"日下部企画財政課長","answer":"あくまでも災害とかそういう一部の例外ということで特別交付金の活用を図るといった、これを今回も改めて主張しましたが、東京都としては提案のもともとの趣旨というのが、これは災害だけではなくて。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"今後も協議は続いていくんでしょうから、当然何％にするかというのはその中で決着をせざるを得ないんでしょうけれども、論議として実際問題としてどこまで続けるのかというとおかしいのかな。区側の考え方というのか、パーセンテージをどうするかという、どこまで論議として続けるというのかな。どこかで打ち切らざるを得ないのかというその辺の考え方はどうでしょうか。","respondent":"日下部企画財政課長","answer":"これは今本来のあるべき論ということで区側としては主張しているわけですけれども、やはり協議、交渉ですから、それだけではなかなか押し切れないというところもありますが、我々としてもやはり早く決着すべきだということには変わりはありませんけれども。","voiceIndex":7,"id":"exchange-002"},{"speaker":"土井委員","kind":"質問・要望","question":"特に第１行目もそうなんですけど、下記により再調整を行う。だれが何をどうするのかさっぱりわからない主語のないやつですよね。これはやはりどこかでもう改めなきゃいけないんじゃないですか、主語をはっきりさせなきゃ。というのがそこら辺ちょっと考え方も含めてお伺いしたいのと。どういう考え方に基づいて加味した額というのは決めるのかというのをちょっと知らせていただきたい。","respondent":"日下部企画財政課長","answer":"１点目の方針、主語がないというご指摘です。この方針自体の性格、確かにおっしゃるようにいろいろ課題はあろうかと思いますが、どうしてこういう表現がずっと続いているのかと言いますと、配分の権限というのは、これは法的にもやはり東京都が持っている。","voiceIndex":9,"id":"exchange-003"},{"speaker":"土井委員","kind":"意見","question":"日本語のおもしろいところで、そういうのがいっぱいあるんです。法律用語にまでありますから、だれがだれをどうするのかさっぱりわからないのがありますよね。それはあるのはいいとは言わないけれども、それをやはりこれからははっきりしていかなきゃいけない時代だと思うんです。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"その単価というものが、だれが決めてどういう方法で見直しがされてきたのかということ、これはつまり１つの標準の区がモデルとして出てくるんですけれども、その考え方１つで財整調整の額も変わってくるわけですから、それはだれがどういうところでつくっていて、また当然見直しもかけていくんでしょうから、どういうふうに見直しをされているのかということ、この２つをお聞きしたい。","respondent":"日下部企画財政課長","answer":"財政調整単価のほうから申し上げますと、これは単価については都区間で協議をしまして、そこでもうかなり細かいものも含めて見直しをしてまいります。例えばさっきご説明申し上げました４ページに基準財政需要額で再調整の中で退職手当費というのがあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"いろいろなケースが災害はあると思うんですよ。ですけれども、あれだけの四半期の場合ですけれども、ワーストに入っている現実があるわけですよね。となれば、やはり未然防止の大きな枠の中で、財政調整協議の中で求めていくということは１つの方向性だと思うんですけれども、そのことについてお答えをもう一度いただきたい。それから、この見直しは、これは毎年やっていらっしゃるんですかね。","respondent":"日下部企画財政課長","answer":"たしか３月に正式な決定通知が参りますけれども、そうするともう実際に今度は８月に当初算定がありますので、それに向けて一応算定の取り組みを進めていくわけですけれども、そういう形で実際の算定はいきますけれども。","voiceIndex":14,"id":"exchange-006"},{"speaker":"土井委員","kind":"意見","question":"平成１９年度の再調整の概要がここにありましたけれども、さっきの５％の部分のルールが決まってきますよね。決まってきますと、場合によっては全然これがない、例えばの話。それによって出てきたものがどこかにあるはずなんだけれども、あるのかないのかわからないんだけれども、平成１９年度はどうなったのかなと。その当初算定残額というのに当たるのか、そこに含まれているのか、どうなのか。","respondent":"日下部企画財政課長","answer":"当初算定残というのはあくまで普通交付金のほうの算定残です。こちらの５ページはあくまでも特別交付金の５％の中で結果的に残った場合について配分をするというようなことで、４ページの当初算定残とはちょっと別の性格のものだというふうに理解をしております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"原委員","kind":"質問・要望","question":"使用貸借、今のことなんですけど２点だけ。それと、これはもう現実には買い取ることができるんでしょうから問題も発生しないので、一般の使用貸借という解釈でよろしいのか。一番大きいのは法的な収益性のものが発生するじゃないですか。使用貸借で借りるというものも区としてはプラスが発生するわけなんで、その２点ですね。保険の関係とそこだけわかれば教えていただきたい。","respondent":"中島経理課長","answer":"施設の管理関係、私どもでやっておりますのでお答えしますけれども、施設を使用するということで当面イコール管理もしていくですので、当然建物等につきましては必要な保険等に加入していくということになろうかと思います。","voiceIndex":29,"id":"exchange-008"}]},{"id":"topic-02","title":"改めまして２の所管事務調査、都と区の関係における諸課題","agenda":"改めまして２の所管事務調査、都と区の関係における諸課題","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"それを考えながら４４４項目と区域のあり方が出てきた。だから、どうしても確認したいのが、区長がいらっしゃらないのであれだけれども、区長会がこのことに対してどういう意思を持って、このあり方検討委員会そのものはどういう位置づけであって、結論をいつまでに導き出そうとしているのかという確認をしたいと思っていますので、そのことの話を伺いたいのと。その２つを聞かせていただきたいと思います。","respondent":"日下部企画財政課長","answer":"確かに４４４項目をこれから４月以降、検討するとなると大変な作業にはなりますけれども、その辺は２３区は一生懸命頑張っている。","voiceIndex":38,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると、例えば今までの幹事会の中で検討してきた問題が、結論としては都区双方の意見が相対立してまとまらなかった。４月以降再度調整ということになっているんですよね。やはりそのことについては区長からも答弁をいただきたいと思うんです、大きな話ですから。場合によっては、これは具体的に話が煮詰まっていく段階であれば、いわばいろいろな事務が理事者によってまた見えてくるわけじゃないですか。","respondent":"本間副区長","answer":"まさにおっしゃる状況にあるわけなんですが、そもそもこの検討の進め方の基本的な考え方というのはきちんと整理はされております。","voiceIndex":40,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"非常に心強い話をいただいて思ったんですけれども、こと東京都が相手な話ですから、今までいろいろな歴史があって、場合によっては区側が勝ったり負けたりしてきたことがあった。結果として、来年度中の中になってくるでしょうけれども、この中のどれぐらいが来るかはもちろん楽観はできないけれども、自治の確立のためにぜひ進めていっていただきたい、区側の理論で、それをお願いしようと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-011"},{"speaker":"土井委員","kind":"質問","question":"そういう意味での区側の意志統一というようなものが、どういう形で急いで進められつつあるのか。最後のところにいって話をしていたら、いや、おれのところは実はやりたくないんだから、都でよろしくお願いしますなんていうのが出てきちゃったらおもしろくも何ともなくなっちゃうので、その辺はいかがなんでしょうか。","respondent":"本間副区長","answer":"その前に２３区それぞれの考え方がありますから、そういう意味では今、それぞれの項目に対してそれぞれの区の考え方を調査するものというのは、これは当然ながらやっているわけでございまして、それを先ほど言ったとりまとめをしなければならないということで。","voiceIndex":43,"id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"当然そういうふうに進めていかなければならないところに進むということなんでしょう。ただ、先ほども言いましたように、おしりが引っかかっているものですから、そこに上下水道というでかい課題が残っているわけですよ。その時間がしっかり確保するためにはできるだけ早く前倒しでそこら辺を進めていかなければならないという状況ではないかと思うんですよね。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"考え方、とらえ方としてちょっとよくわからないところがあるのでお聞きしたいんですけれども、この上下水道の話もそうなんですけれども、４４４項目が決定した後にどうなるかという部分なのかもしれないんですけれども、財源の見方として、まさに上下水道みたいな大きなものも含めて確定をした際に、今の財政調整制度で単純に財源をぽんと上乗せをして進めるものなのかどうか。そこをお聞きしたい。","respondent":"日下部企画財政課長","answer":"財政上の問題ですので私のほうからお答えしますが、前回もたしか区長が若干触れたと思いますけれども、事務が移管になる。","voiceIndex":46,"id":"exchange-014"},{"speaker":"武内副委員長","kind":"質問","question":"これについてはどのような展開というんですかね、例えばそれ全部区のほうで新たに足りない分を採用してやるのか。それとも東京都で今まで担っていた技術なり、そういうものがある人をどうするのかとか、もっと言えば、じゃあ全部４４４移った場合に、それに携わっていた東京都の職員というのは大幅にやめざるを得なくなるわけですよね、極端なことを言えばですね。どんなようになっているんでしょうかね。","respondent":"日下部企画財政課長","answer":"一定の経過措置を経て今、清掃の職員の方たちは平成１８年度から今度は区の職員に経過措置を経て切りかわったというような経過がありますが、大きい事業の場合はやはりそういうことも当然考えられますし、比較的そこまでいかないような、そういうものも考えられますので。","voiceIndex":48,"id":"exchange-015"},{"speaker":"武内副委員長","kind":"質問・要望","question":"そういうのもまた検討していただきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-016"},{"speaker":"林委員長","kind":"質問","question":"そうします。参考にしていただければと思います。土井委員の一般質問の中で出てきた地方公共団体の公会計についての。これについては何か質問あるいはその他ありましたら、次回以降の総務委員会で取り扱っていきたいというふうに思っていますので、参考にしてください。どうもありがとうございました。その他ありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1778#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":31020,"voices":60}},{"id":"h20-20080227-14","meetingId":"h20-cm02","date":"2008年2月27日","dateIso":"2008-02-27","committee":"行財政改革特別委員会","time":"午前１０時０３分～午後２時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の契約のあり方に関すること","agenda":"の契約のあり方に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"思いつくままになんですけれども、幾つか質問をさせてください。確かに仕事の内容によって評価基準というのはそれぞれ個別に検討されることとは思うんですけれども、それにしても何か評価基準のつくり方の枠組みみたいなものはあるんでしょうか。１つの質問として、評価の基準のつくり方と、それから最低限の、これとこれとこれは必須みたいな考え方はあるかどうか、教えください。","respondent":"中島経理課長","answer":"この評価基準ですけれども、これは各所管で定める実施要領に基づきまして定めてあります。項目の基本的な部分で出てありますけれども、基本的な業務に対する考え方とか、実施体制とか、実績等が中心のものということで、この辺については必ず確認するということになってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"阿部委員","kind":"質問","question":"私の記憶が間違いでなければ、学校給食については、昨年、結局受託したところが仕事をやり切れなくて、委託を業者の側から返してもらったと言ったらいいんですかね、そういうことがあったかと思います。そういうことを考えると、委託の仕事の種類によって、実績の重視の仕方ですとかが変わってくるんじゃないかと思うんですけれども、その仕事による分類みたいなことはされているんでしょうか。","respondent":"中島経理課長","answer":"実績の部分ですけれども、学校給食につきましては、実績は２３区内で学校給食の、これはセンター方式とかじゃなくて、自校方式の学校での実績があるかどうかということを基準の１つとして定めておりまして、今、委員がご指摘の業者につきましても、学校での実績があったです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"阿部委員","kind":"意見","question":"ここをもうちょっと突っ込ませてください。学校給食のほうなんですけれども、要は当該の業者は確かに２３区内の別の学校で実績があったと。それなりに評価をされていた。要は区の基準を全部クリアしているのにできなかったということは、基準に何か足りないものがあったと考えるべきだと思うんですけれども、その辺についてはどういったことが今後必要だと思われますか。","respondent":"中島経理課長","answer":"ただ今回、大間窪小学校に関しては、所管のほうからの話によりますと、配置されているチーフあるいはサブチーフの方のさまざまな個人的な家庭の事情等があって、来ることができなくなってしまって、学校の調理業務の委託が実質継続困難になったということで聞いてありますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"ですから、まさにそこだと思うんですね。だけれども、さらにプラス１つ広げるだけの人的余裕は持っていなかった。つまり１人や２人現場の人がやめたからといって、受託が不可能になってしまうというのは、やっぱり組織としては足りないものがある。要は１人いなくなったら回らなくなるような業者であれば、さらに別の評価項目も必要なんじゃないか、そういう話です。","respondent":"中島経理課長","answer":"結果として、大間窪小学校の業務からは撤退したいという要望が逆に事業者のほうからございまして、それは早めにあったですので、そういった意味では児童のほうにそれほど影響がないような形の中での撤退。","voiceIndex":11,"id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"でないと、同じような規模、同じような悩みを抱えた同じような業者がまた落札をして、また同じように、やっぱり１人やめたから、今、やめるなんていうことはよくあるわけですから、やっぱりやめたからこの給食は続きませんでしたということになっては困るんじゃないかという話をさせていただきました。","respondent":"中島経理課長","answer":"それと総合評価方式そのものも、まだ今年で２年目という状況ですので、そういった業者選定にあたっては、まだ検討しなければならない部分というのは当然あろうかと思いますので、今後その辺も含めまして、十分検討させていただきたいと考えています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"この資料の学校給食についての評価基準と、戸籍証明の郵送の評価基準とありますけれども、この評価基準そのものは、冒頭に説明のあった事務の流れの中のどこで使われるものなのか、それをまず説明いただけますでしょうか。","respondent":"中島経理課長","answer":"この評価基準を使うところですけれども、１ページ目の資料の右側の主管課の部分のところの中段ぐらいですけれども、審査委員会の開催になってございまして、そこに履行能力等の審査ですけれども、この中でこの評価基準を使いながら審査を行っていくです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"その審査委員会というのはどういう構成というのか、どういう形なのかご説明いただきたいのと、それと評価基準を見る、いわゆる設問にはなっているんですけれども、それに対して、基準というならば指数なのか、点数なのか、５０点満点という話もあったんですけれども、この基準の中にはそういうものがないもので、よく説明の意味がわからなかったので、評価基準の基準というんですかね。","respondent":"中島経理課長","answer":"１点目の審査委員会のメンバーですけれども、所管部長を委員長といたしまして、関係する所管課長、それと、この業務と直接かかわっていない課長をメンバーに入れて評定を行っているということで、実際に審査委員会という名称になっておりますけれども、面接をして。","voiceIndex":17,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"配点票というのが、５段階で４なのか、３なのか、５なのかというものと同時に、必ず必須というものがなければ、見落としのものが生まれてくるんじゃないかと思うんですけれども、その必須のものがあるのかないのかご説明いただきたい。こういうところの採点の仕組みというか、評価の仕組みは何を基準にどう確認しているかというのがいまいち説明の中で見えてこないので、ご説明いただけますか。","respondent":"中島経理課長","answer":"それと、評価基準の中で必須というか重要なものとして考えているのが、これはどこの課もそうですけれども、実施体制ですね。実施体制についてが一番どこの課も力を入れているところです。ですから、全体の評点なんかを見ましても、実施体制につきまして比較的重く見ているです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明の際にはこういう体制でやりますよとなるんだけれども、実際にその体制が整うかどうかは、契約をした後の話になる。欠員、異動が生じた場合、この「安定」というのはどのように確認するのか。どの会社ももちろん熱意を持って説明する。それは仕事を受けたいからそうでしょうけれども、客観的にどういうふうに確認をするのか、そこがまだまだ不十分なのかなと思うんですけれども、いかがなんでしょうか。","respondent":"中島経理課長","answer":"それと実際、例えばヒアリングの中で実施体制を確認して、これはできそうだという、もちろん事業者のほうはちゃんとできますと答えるんでしょうけれども、その中で、その話の中身と言い方と、あるいはその会社が抱えている人員体制もありますし、その中で私どもが。","voiceIndex":21,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"配点票そのものがどこに重点を置いて、５０点満点ということだけは説明があるんですけれども、じゃ、何点以上なのか、配点票そのものを示していただけないと、説明がどうも説得感に欠けてしまうんですけれども、配点票というのは、おそらく事業ごとによって違うのは説明の中でわかるんですけれども、ぜひその配点票を見せていただきたいと思うんですけれども、いかがなんでしょうか。","respondent":"中島経理課長","answer":"考え方として、先ほど申し上げましたように、実施体制について一番大きな要素を持って考えているです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"どうしても説明で腑に落ちないのは、それぞれの会社の評価の点数を公表しろと言っているわけじゃなくて、評価する前の配点票というのはいわゆる物差しなわけですよね。行政の側からここは大事だと思う点、ここは必須だと思う点、その物差しというのは客観的なものですから、それは公表しないという説明がよく意味がわからないので、その理由をもうちょっと教えていただきたいんですね。","respondent":"田中総務部長","answer":"採点基準の公表ができるかどうかという問題かと思いますけれども、このファクターというのは、例えば先ほど大間窪小学校の話がございましたけれども、そこで問題になったのは、2)にあります欠員・異動等があった場合の体制をどう考えているか。","voiceIndex":25,"id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"この簡易型総合評価方式、昨年の９月決定で実施されたということなんですけれども、そうすると、今のところ、この戸籍証明の関係と学校給食の調理代行のこの２つの事業を、この簡易型の総合評価方式でやっていらっしゃるんですか。それともほかにまだやっているかどうか。","respondent":"中島経理課長","answer":"まだほかにもやってございまして、今年につきましても、すまいるスクールとか、そういった関係の事業につきましてもやっておりまして、今後徐々に拡大していきたいという考え方です。","voiceIndex":27,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問","question":"以前にいただいた資料によると、例えば工事案件なんかも一応範囲には入れているような表現があるんですけれども、例えば工事請負業者の指名停止基準による指名停止処分を受けていないこととか、そういう条件が入っているんですけれども、というのは、今のところは多分やっていないんでしょうけれども、行く行くは工事案件なんかも考えていくということなんですかね。","respondent":"中島経理課長","answer":"ただいま試行して拡大していくというのは、委託契約の関係をやってありますけれども、今後、工事案件につきましても総合評価を導入していくということで、平成２０年度に向けて、１件になるのか２件になるのかあれですけれども、実際。","voiceIndex":29,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"ちょっとお聞きしたいのが、いわゆる予定価格に対しての、５０点満点でいろいろな基準がありますね。それと履行能力ですか。これが５０点満点で、両方で１００点でやると。ただ履行能力のほうも５０点満点の評価がそれぞれ出ますよね。そういった場合というのは、まず予定価格自体が超えちゃうと、履行能力があろうがなかろうが、すべてそれは失格になっちゃうんでしょうか。","respondent":"中島経理課長","answer":"ですから、幾らで入れているかはわからないことになりますので、審査はやっていくということになりますけれども、ただこの委託につきましては、３,０００万円とか２,０００万円にかからず、予定価格を公表していますので。","voiceIndex":31,"id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"それが例えば先ほどの優先案件というのかわかりませんけれども、あくまで価格が大前提で、価格が上回っちゃったら、ほかの５０点のほうは全く関係ないんだというふうになるのか、それとも価格は価格でだめであっても、例えばそっちのほうを基準として業者を選定することができるのかどうか、そこをお伺いします。","respondent":"中島経理課長","answer":"予定価格につきましては、予定価格を超えて契約することができないとなっていますので、そういった価格の入札があった場合には、実際の評価点が例えば５０点満点だったとしても、その事業者につきましては失格にするです。","voiceIndex":33,"id":"exchange-015"},{"speaker":"林委員","kind":"意見","question":"それが国のほうの基準緩和じゃないけれども、使いやすくするよという話で、ほかの委員会の話で恐縮だけど、総務委員会で芦屋市で総合評価の道路工事の関係を聞いて、こんなのじゃとても入れられないなという実態も聞かせてもらったんだけれども、国のほうの動きというのをまず聞かせてくれますか。","respondent":"中島経理課長","answer":"総合評価に関しましては国で先行してやってございまして、特に地方がなかなか導入できないという一番大きな要素は、学識経験者のかかわり方です。","voiceIndex":35,"id":"exchange-016"},{"speaker":"林委員","kind":"質問","question":"緩和されたからといってすぐ採用というか、品川区で取り入れられるかどうかわかりませんけれども、その辺の情報はきちっととりながら、品川区の実態に合ったというか、いい方法を考えておいてほしいと思います。今日もらった資料の中で幾つかお聞きしていきますけれども、上から４行目、５行目、公告をして公募型の採用をするか、指名型にするか。","respondent":"中島経理課長","answer":"平成１９年度行いました試行の中では、指名型と公募型両方実施しています。実際にその区分けですけれども、原則的には３,０００万円以上の予定価格につきましては公募型で実施する。それ以外につきましては指名型ということで区別をしているです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"そうすると、今は最終決定は金額だけじゃないけれども、公募型、指名型という判断は金額だけで決定をしている。３,０００万円を境にどちらかを採用する。それは経理課で、それとも主管課でということなんですか。","respondent":"中島経理課長","answer":"基本的には協議しながら、最終的な判断は経理課のほうでしています。それと今、お話しした公募型、指名型ですけれども、実際に戸籍の事務につきましては、予定価格が３,０００万円を超えていましたけれども、指名型でやってあります。","voiceIndex":39,"id":"exchange-018"},{"speaker":"林委員","kind":"意見","question":"流れに沿って聞いていきます。この簡易型総合評価方式でいったときには必ず現場説明会をするというのは前、説明されて、先ほど出た工事の場合には現場説明会をしていないということなので、その辺はこれからどういうふうに折り合いをつけていくか。次の２枚にあるような、基準に沿ってここをこういうふうに書きなさいよとか、そういうふうになっているのか、ちょっと簡単に説明してください。","respondent":"中島経理課長","answer":"審査票につきましては、委員ご指摘のとおり、評価基準に沿った形で質問をして、それに書いてもらうという形で現在運用しているです。","voiceIndex":41,"id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"そうすると、例えば戸籍の方は、戸籍証明の交付にあたっての注意点等の考え方はどうですかという、例として。そうすると、ここは記述式になるのかなと思いますけれども、それから、逆に４番なんかは実績がありますかというと、どこどこでやりました、これこれでやりましたという。実績だからそれだけ書いていく。そういう織りまざったような審査票になっているわけですか。","respondent":"中島経理課長","answer":"各所管によってつくり方が若干違っておりまして、要するに記述式でもって全て書かせるやり方もありますし、例えば有資格者が何人と書けばいいようになっている場合もありますし、さまざまそれは工夫しながら、あるいは事業者が書きやすいようなものにして書いてもらっているです。","voiceIndex":43,"id":"exchange-020"},{"speaker":"林委員","kind":"質問","question":"それを斟酌するということになるわけですか。","respondent":"中島経理課長","answer":"ちょっと言葉が的確かどうかあれですけれども、審査票で出していただいたものの裏付けをとるというか、本当に書いたとおりできそうかどうかというのを、５人の部課長が見ているわけですから、そういった中でいろいろなことを聞きながら、その辺を判断していくです。","voiceIndex":45,"id":"exchange-021"},{"speaker":"林委員","kind":"質問","question":"審査票までわかりました。学識経験者という形で外部の方が入るということは、１つのステップにならないかなという気がするんですけれども、いかがでしょうか。","respondent":"中島経理課長","answer":"ただ施行規則のほうで定めているのは、審査委員会に入るということではなくて、例えば審査委員会の配点基準だとか、例えば審査委員会をやった結果、この業者にしようと思いますけれども、よろしいでしょうかという、そういったことをお諮りしながら決めていくということで。","voiceIndex":47,"id":"exchange-022"},{"speaker":"林委員","kind":"意見","question":"そうすると、例えば戸籍で言うと、これだけが審査票に書いてあるとすれば１６問あるわけで、その１６問に、１番目はこういうふうに思っていますということなんだろうと思います。一番下は、さっき言ったように何々でやりました、何々で何年にやりましたというような。それ以外にヒアリングをするということは、これ以外に重要なファクターを区としては考えているという。","respondent":"田中総務部長","answer":"ですから、今後もこの制度、それぞれの主管が毎年の反省を含めましていろいろな形の評価基準、あるいは評価のファクターに対する採点といいますか、そういうものを精査しながら、いい契約ができるようにしていきたいという考え方です。","voiceIndex":49,"id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"もう１つ、最後に言いたかったのは随意契約ということを、今、国、都道府県、市町村を含めて、随契のよしあし、その随契の精度を固めようと区のほうはこういう形を、あるいはこれをもっと進化させていこうと思っているんだけれども、そうすると、随契というのは相当な比率でたくさんあるんだけれども、これからも指名、随契という比率は変わらないと僕らは理解しておいていいんですか。","respondent":"田中総務部長","answer":"事業者の方が説明に来るときに、どういう責任者の方が来るかとか、メンバー構成、それからやりとりを私どもがいたしまして、それでこの会社は本当にきちんとした仕事をしてくれるかどうかというのを見定めて、評価をするのが一番のポイントかと考えています。","voiceIndex":51,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"「原則として」という言葉がついているので、ヒアリングを行わない場合もあるのかどうか、その点と、あと今日の資料は戸籍と学校給食なんですが、具体的にこの辺で審査の書類を見ながらヒアリングをしたときに、実際にどのくらいの時間をかけてこのヒアリングが行われているのか、ちょっとその辺を教えてください。","respondent":"中島経理課長","answer":"ヒアリングの部分の原則ですけれども、総合評価方式の対象になるのはさまざまな範囲が出てくるという考え方でございまして、最終的には所管の判断ですけれども、原則的にはヒアリングを実施していくですけれども。","voiceIndex":53,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"審査票の書類だけで大丈夫と判断されるところというのは、具体的にどういうところがあるのか、そこを教えてほしいのと、二、三十分で書類の審査をしているということなんですけれども、この間いただいた資料の中に、評定基準票の裏にさっき話にあった票があったんです、今、一生懸命探したら。二、三十分くらいで形式的に流れてしまうんじゃないかなと思われるんですが、その点はいかがでしょうか。","respondent":"中島経理課長","answer":"一番最後の時間の関係ですけれども、ヒアリングは１社２０分から３０分ということで考えて実施しています。","voiceIndex":55,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は先ほど来のやりとりを聞いていて、ここは所管の部長や行政の関係者だけでなく、やはり外部の方がしっかり入るのが大事であるなというのを１点感じているのと、あとこの情報が正しいかどうか、虚偽の内容の報告があったときに、どうやってそこがチェックできるのかなというのが１点疑問点と、あとあってはならないけれども、例えば判断する側のお手盛りがあったりとか。","respondent":"中島経理課長","answer":"今後の問題として、審査委員会に学識経験者を入れたらどうかというお話ですけれども、先ほど林委員のご質問にも総務部長がお答えしましたけれども、今後の検討すべき課題であると考えています。","voiceIndex":57,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の配置基準のところなんですが、何食を何時までにつくってほしい。その辺までも含めて把握をしていくというのが、責任ある体制であるのではないかなと思いますが、その辺はいかがでしょうか。","respondent":"中島経理課長","answer":"委託につきましては、先ほども申しました何食を何時までに提供してもらうんですよという基本の仕様がありますので、それにつきまして予定価格を提示しているですので。","voiceIndex":59,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"この点をしっかりと把握しながら仕事をしないと、それこそ業者任せになってしまうというところにおいては、ぜひ委託先のそういった労働環境、賃金も含めてそういうところもきちんと把握をするということを踏まえていかないと、委託になじまない状況になってしまうと思うので、その点をもう１回と、あと３ページのところの代行保証制度に加入しているか、これは必須条件と書いてあるんですけれども、この辺。","respondent":"田中総務部長、中島経理課長","answer":"その従業員の方とその会社の雇用関係、そういう中での確認をする場合もございまして、それはあくまで従業員の方と会社との関係でございまして、私どもは会社がどういうふうにこの業務を。それと表現の問題で、委託した場合の安心できる考え方を持っているかどうなのかということですけれども、これにつきましては、要するに区の学校給食の方針と一致しているかとか。","voiceIndex":61,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"以前にふじみ野市のプールでお子さんが吸い込まれて亡くなるような、あれも委託のその先の委託ですよね。こういうところまでチェックをしなかったら、安心して任せられないということになると思うんです。そういった面では、賃金のこと１つとっても、違法、脱法行為がないのかどうか。だから、総務部長の会社の内部には立ち入れないというそこのところは、そうではないと思うんですが、いかがでしょうか。","respondent":"田中総務部長","answer":"これはあくまで反省点として、よりその辺の確認を今後もさせていただきたいですので、これはあくまで会社の内部に立ち入って、幾らもらっているから安心だとか云々という問題ではないのかなと認識しております。","voiceIndex":64,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺をもう１回確認と、あと本当に品川区のところで再委託がないのかどうか、そういうチェックって本当にされているのかどうか。その辺までも含めてぜひチェックをしていただきたいんですが、もし答えることがありましたらお願いします。人材派遣がもしも業者のところに入っていたら再委託になると私は考えているんですけれども、いかがでしょうか。","respondent":"中島経理課長、田中総務部長","answer":"再委託の話ですけれども、委託全般の中で、一部、元請けというんですかね、請けたところが一部委託するということは可能だと考えています。原則と言ったのはそういう意味でございまして、ただそういう意味で言いますと、どういう形態で今回の、例えば給食代行の中で、２の1)に人員数（有資格者数）、配置基準、必ずヒアリングの中で確認等をさせていただいてありますので。","voiceIndex":66,"id":"exchange-031"},{"speaker":"山内委員","kind":"確認","question":"確認をさせてください。指名型にするのか公募型にするのかというのは先ほどご説明がございましたが、業者の選定というか、その時点での公募型、指名型で業者を何社か選定されると思うんですが、まずその業者の選定基準と、それから案件によって違うんでしょうけれども、大体何社くらいの業者が選定され、またその選定をされる方はどなたなのかということを教えてください。","respondent":"中島経理課長","answer":"指名の場合ですけれども、通常、額によるんですけれども、３,０００万円以上で指名する場合につきましては、通常、公告案件になるんですけれども、事情によって指名でやる場合につきましては、指名選定委員会というものを開いて、そういったものを通して指名していくです。","voiceIndex":69,"id":"exchange-032"},{"speaker":"山内委員","kind":"質問","question":"そうすると、この方式をとられますと、会社は熱意を持っているけれども、なかなか参加できないというか、そういうことになりかねないのかなとちょっと私は想像したんですが、その辺の兼ね合いというのはどうなんでしょうか。","respondent":"中島経理課長","answer":"今日論議いただいている調理代行とか戸籍の郵送業務につきましては、若干どこの業者でもできるというものではないんですけれども、委託にしても個人にしてもさまざまな案件がありますので、指名する場合にも、例えば新しく品川区で起業した企業とかがあれば、指名してみて。","voiceIndex":71,"id":"exchange-033"},{"speaker":"山内委員","kind":"質問","question":"そうしますと、そういう業者が例えば窓口にいろいろな説明を受けたいといったときは、そのような形で説明というか、そのようなことをしていただけるようなサービスというのはあるんですか。","respondent":"中島経理課長","answer":"どこの自治体もそうですけれども、基本的に区の仕事をする場合には、まず登録をしていただくということになりますので、その辺の説明はするのと、登録する場合、今、インターネットを使ってやりますので、多少困難な部分があるんですけれども。","voiceIndex":73,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"先ほど飯沼委員からのご質問の中で、虚偽申告のチェックはという質問があって、経理課長のほうから実績で判断していくのだというご答弁だったと思いますが、虚偽申告というものに対してペナルティーというものも事前に設定しておいたほうがいいのではないかと思いますし、それはきちんと実施要綱の中にも今、そういったことは条文としては入っていないみたいですけれども。","respondent":"中島経理課長","answer":"どういうことの部分が虚偽だったのかということもあろうかと思いますけれども、私どもで業者を設定した後に取り消すということがあり得るとすれば、例えば給食代行なんかで有資格者の確認をしていますけれども、当然証明書は添付してもらっているんですけれども。","voiceIndex":75,"id":"exchange-035"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"審査票に書いてもらうのは、例えばこの左側の４項目ぐらいを審査票で書いてもらうということでよろしいですか。そこをちょっと確認させてください。","respondent":"中島経理課長","answer":"項目のこの４つにつきましては最低書きますけれども、例えば実施体制の中で、従事者の人数とか、体制とか、例えば責任者の役割とか、書きやすいものについては人数だけ入れられるようにできているとか、そういった工夫はやってあります。","voiceIndex":77,"id":"exchange-036"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"事業者にとっては出ているかどうかで大分変わると思うんですけれども。","respondent":"中島経理課長","answer":"戸籍で言いますと、基本的に要求要点につきましては、審査票の中に記入させていただいているです。","voiceIndex":79,"id":"exchange-037"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"最後に確認します。この紙は、今、委員会に出ていますけれども、これと同じものを事業者も見ているから、まずい書類というと変ですけれども、判断基準に影響を及ぼす書類ではないということで判断していいんでしょうか。","respondent":"中島経理課長","answer":"基本的にはこの評価基準そのものは出してございません。審査票という形で出しておりますので、一部変わっている可能性もありますので、全く同じものにはなっていないです。基本的にはこの中身を聞いているです。","voiceIndex":81,"id":"exchange-038"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"これを例えば後で評価、審査しますよね。審査した結果として点数が出る。点数は公表すると思うんですけれども、その審査の内容、こういうものだったよということも表には出ない書類なのか。というのは、これがあまり出過ぎちゃって、要するにここに力点を入れて書けばいいという、虚偽じゃないけれども、重点項目が重く見えてしまう書類なのかどうかということで確認をしたい。","respondent":"中島経理課長","answer":"この評価基準は要領の中に載ってありますので、そういった意味では別に外に出ていっても、白紙の状態で出ていくことについては問題ないと考えています。","voiceIndex":83,"id":"exchange-039"},{"speaker":"高橋委員","kind":"質問","question":"学校給食ですが、大間窪小と荏原四中でちょっと問題があったので、２番の人的なところをちょっと重く見ようということはあったんですが、この前、鈴ヶ森小学校でノロウイルスではないかという集団欠席があって、そこでは給食に問題はなかったわけですけれども、その対応等を踏まえて、４番の事故・災害等緊急時の体制について、評価基準を生かしてこの辺をもう少し変えるとか。","respondent":"中島経理課長、堀越行財政改革担当課長","answer":"これは昨年とどこが違うのかというのはチェックしていないんですけれども、所管として、先ほど総務部長もお答えしましたけれども、一遍決めたこの評価基準が、これでもってずっといくということではなくて。指定管理者に関する運用についてご説明します。本委員会では、これまで昨年の６月に指定管理者制度の概要、引き続きまして７月にモニタリング評価のガイドラインについてご説明しています。","voiceIndex":85,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"モニタリング・評価ガイドラインを平成１９年３月に策定して、今の説明ですと、今年の４月以降運用を開始するということでよろしかったでしょうか。その中で、いわゆる利用者アンケートの調査というのは、どんなふうに具体的に運用されていくのか、今の現状、検討されているところを少し教えていただきたいと思うんですけれども、いかがでしょうか。","respondent":"堀越行財政改革担当課長","answer":"４月から実際にモニタリングという形で実施しているというものです。４月から実施ということで、平成１８年度の状況について事業報告書を受けて、実施状況の確認と評価という形で進めております。","voiceIndex":90,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用者アンケートのほうは既に幾つかの施設で行われているということですけれども、どんな施設で既に実施されているのか、もう少しそこを詳しく教えていただきたいのと、そこで寄せられた利用者の方のご意見などが、改めてモニタリング・評価の中でどのように反映され、運用改善に結びついているのか、その流れを教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"利用者の意見の反映ですけれども、例えばそういったご意見をお伺いして、新しいサービスの展開について、実際の指定管理者のほうで新しいマニュアルをつくったりですとか、新規のサービスの検討を始めたりですとか、そういうサービスアップについてもお話を伺っております。","voiceIndex":92,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用者アンケートがどういう設問でどういう形でどういう実施がされているのかもあわせて教えていただきたいのと、集約されているものも、ぜひ見せていただきたいなと思っているんですけれども、いかがなんでしょうか。","respondent":"堀越行財政改革担当課長","answer":"具体的には施設のいろいろな特性等に応じて工夫していく、つくられている、そのように認識をしております。","voiceIndex":94,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"議会としてはこの議決案件だけに、そこの現場の利用者の具体的にどういう声が上がっているかという、そのアンケートを集約したものというんですかね、別にアンケート用紙そのままをコピーしてくれとは言いませんから、どういう声が、どういう傾向が、どういうアンケートが行われているか。","respondent":"堀越行財政改革担当課長","answer":"利用者アンケートは指定管理者のほうで基本的には行うというふうにしていますので、それをそのままお出しするというのは、なかなかいろいろな部分で難しい部分もあるのかなと思っています。","voiceIndex":96,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜそれが出せないのか、今のお話ですと難しいというご説明でしたけれども、その難しい理由を教えていただきたいのと、それからこれは繰り返しになりますけれども、モニタリングの際、総括シートはありますけれども、僕らが評価する基礎的データもここには記されておりませんし、事業報告書、事業計画書、収支のわかるもの、そうした基礎的データは改善していかないと、評価の評価では評価しようがない。","respondent":"堀越行財政改革担当課長","answer":"それから利用者満足度のいろいろな考え方ですけれども、総括シートの統計情報のところにも、例示としてではありますが、利用者満足度の状況ですとか、そういったものも載せてありますので、そういったところでどのような利用者の方の傾向があるかという部分についても。","voiceIndex":98,"id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"伺っているのは、指定管理者自身が行ったアンケートをなぜ見せていただけないのかということなんですね。お答えになっていないですね。利用者アンケートをなぜ見せていただけないのか。何らかの集約だったり、具体的なご意見だったり、傾向だったり、いろいろ指標があるかと思うんですけれども、なぜそれを出していただけないのか、そこがわからないので、そこをご説明ください。","respondent":"堀越行財政改革担当課長","answer":"いろいろな指定管理者から出てくる書類を含めて、事業報告書ですとか、事業計画書ですとか、それは指定管理者が保有する文書ですので、今、コピーではないというお話でしたけれども、そのような現物に近いような形でお出しするというのはなかなか難しいかなと考えています。","voiceIndex":100,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話ですと、統計的な傾向はお示ししていただけるということでよろしいのかということを１つ確認させてください。アンケートの集約を、何も個人情報まで含めて、どこどこのだれが答えた答を出してくれと言っているわけではなく、例えば品川区も広報広聴課のほうで区民アンケートを行って、冊子をつくっていますよね。今、区民の方がこういうご意見やご要望の傾向があるというのを出しているわけですよね。","respondent":"堀越行財政改革担当課長","answer":"ご指摘のあった点については、今後のいろいろな課題の一つとして受けとめて、研究なり検討なりという形で進めていきたいと考えております。","voiceIndex":102,"id":"exchange-047"},{"speaker":"林委員","kind":"確認","question":"１つだけ確認させてください。４番のモニタリングをする。もう既に平成１９年度については始まっているわけですよね。平成１９年度のいわゆる金額の確定はされていて、平成２０年度の契約金額についての交渉というか、それにこのモニタリングがどう生かされるか、お金のことに限って言うと、全くこれは別の過程としてあって、金額については全く違うことで受託者との契約をすると理解しておいていいんですか。","respondent":"堀越行財政改革担当課長","answer":"ですから、モニタリングの実施状況を踏まえて、事業者の提案も踏まえながら、委託料についても検討をして算出していくという形になろうかと思います。","voiceIndex":106,"id":"exchange-048"},{"speaker":"林委員","kind":"提案","question":"そうすると、予算編成ですとか財政側へのシーリングというか、事業部での提案みたいなものにこれが生かされる。それには増額ということも出てくるわけで、そういう契約のほうにこのモニタリングがどこでどの担当と連携をしていくのか。それから行財政改革担当課長、それから企画財政課というところとどういう連携をとってこのモニタリングが生かされるのかという話をちょっと聞かせてください。","respondent":"福田企画部長","answer":"この表にもあったと思ったんですが、事業部経営会議の検証、下の表の下から２段目、８月です。事業部経営会議における検証、これが区として全体の評価をするところと位置づけております。","voiceIndex":108,"id":"exchange-049"},{"speaker":"林委員","kind":"質問","question":"そんな中にこのモニタリングをしたこと、評価をしたこと、翌年度に生かせること、それは内容の部分と契約金額の部分、制度の目的の3)に当たる部分だけれども、それを加味して総合的に予算編成の中で生かしていくということをしなければ、何のためにこれをやるかということが問われてくるわけですから、その辺、しっかり事業部経営会議というところで出るそうですから、経営感覚を持った中で、きちんと内容。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-050"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点だけお聞きしたいんですが、一番初めの制度の目的に３つを挙げられているんですが、１つ目のは非常によくわかる、民間事業者のノウハウの活用というのはわかるんですが、残りの２つの高いサービスの提供と経費の節減について、まず高いサービスの提供、なぜ民間が高いサービスをできるかというと、その１つはやっぱり競争があるからこそ高いサービスの向上に心がけて民間はやっていると思うんですが。","respondent":"堀越行財政改革担当課長","answer":"ただ経費の削減だけではなくて、サービスの向上と経費の削減の両面を目的といたしまして、施設がより最小の経費で最大の効果が得られるような、そういったものを目指している、そういった考えに立って運営をしているというものです。","voiceIndex":111,"id":"exchange-051"},{"speaker":"石田（慎）委員","kind":"質問","question":"ぜひまずチェック体制をしっかりすることによって競争が生まれるのかなと思うので、ぜひ今後も一層チェックをしっかりしていただければと思います。経費のことなんですが、以前、指定管理者制度を導入する前とどのくらい経費の削減ができたのか、今後どのくらい出そうな見込みというか、もしわかったら教えていただければと思います。","respondent":"堀越行財政改革担当課長","answer":"今提案があったというのはきゅりあんの例ですけれども、そのほか、総合体育館ですとか、品川児童学園ですとか、そういったところで、細かい金額はいろいろな年次の協定によって業務が多少増減するようなところもありますので、単純な比較というのはなかなか難しいんですけれども。","voiceIndex":113,"id":"exchange-052"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"経費の節減はせっかくこの制度の目的の３つに選ばれているので、ぜひ今後も進めていただければなと思うんですが、最後に１点、これは要望なんですが、この民間事業者のノウハウの活用、そして高いサービスの提供、経費の節減というせっかく３つがありまして、これをただ指定管理者制度だけにおさまらず、それを今度はほかの指定管理者制度を導入していない業務にも、ぜひこれを研究していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-053"},{"speaker":"阿部委員","kind":"質問・要望","question":"先ほどのご答弁の中で、競争状態がないとというお話がありましたが、１つまず教えていただきたいのが、管理委託から指定管理者制度になったものの中で、従来の管理者がそのまま指定管理者になっているという比率というのはどのくらいかおわかりでしょうか。","respondent":"堀越行財政改革担当課長","answer":"ただ例えば自転車駐車場の場合ですとか、住宅の場合ですとか、公募をかけてきておりますので、これから制度の運営、それから例えば品川文化振興事業団ですと、区との文化施策とのかかわりですとか、いろいろな部分で総合的に効果的な管理を行うところという観点から考えますと。","voiceIndex":116,"id":"exchange-054"},{"speaker":"阿部委員","kind":"質問","question":"指定管理者制度は、先ほど石田慎吾委員が聞いていたプラスの面がある一方で、どうしても手続的にブラックボックス化しやすいというデメリットもあるわけですね。ちょっと話を戻しまして、全体的なことについてお伺いしたいんですけれども、平成１９年度は８３カ所導入していたかと思うんですが、今後の見通しというのはどのようになっているんですか。","respondent":"堀越行財政改革担当課長","answer":"今後ですけれども、今のところはおおむねほぼ指定管理者導入を予定していた施設については導入しておりますので、指定管理者制度に関する基本方針というものを平成１７年に定めておりますけれども、その中でも指定管理の制度の活用を基本としておりますので、これを活用していく。","voiceIndex":118,"id":"exchange-055"},{"speaker":"阿部委員","kind":"質問","question":"平成２０年度はこの８３施設のままである見通しでよろしいでしょうか。","respondent":"堀越行財政改革担当課長","answer":"平成２０年度は８３施設という形になります。","voiceIndex":120,"id":"exchange-056"},{"speaker":"阿部委員","kind":"質問","question":"例えばアンケート内容を全部精査して公開して検討してというのは難しいかと思うんですけれども、総合得点が相対的に振るわなかったところだけについてでも、それについてさらにどこが悪かったのかを公に検証するようなことはできないかと思っているんですが、いかがでしょうか。","respondent":"堀越行財政改革担当課長","answer":"こういう積極的な取り組みをしているのでこういういい評価があったですとか、そういうものも資料として、どのような形になるかはちょっと検討させていただきたいとは思いますけれども、指定管理者側とも協議をしながら。","voiceIndex":122,"id":"exchange-057"},{"speaker":"阿部委員","kind":"質問","question":"この品川区においても、個別の申請があったときにそれを出すかどうかというだけではなくて、基本的な財務状況などについては、最初から出していてもいいのではないかと思うんですが、その辺はいかがでしょうか。","respondent":"堀越行財政改革担当課長","answer":"なおかつ区とも協議をしながら、情報公開に対しては対応していくという対応の仕方をしています。したがいまして、現時点ではそのような対応で進めていきたいと考えております。","voiceIndex":124,"id":"exchange-058"},{"speaker":"阿部委員","kind":"提案","question":"私の理解力があまりよくなかったのかもしれません。そういう意味では、この指定管理者制度も当然公の目的で公のお金が入って事業を行っているわけですから、その団体の基本的な財務情報ぐらいは、請求しなくてもわかる状態にしておいてよいのではないかというご提案で、それについては特にそういう考えはないという意味でのご答弁だったんでしょうか。","respondent":"福田企画部長","answer":"ご指摘のとおり、例えば連結決算の財務諸表などを見ますと、区と一定の関係のある団体については、例えばバランスシートを策定して、そして区のバランスシートとともに公開する、こういう大きな国の流れがあると認識しております。","voiceIndex":126,"id":"exchange-059"},{"speaker":"阿部委員","kind":"質問・要望","question":"この場で結論を出してほしいとは思っておりません。ただ他団体といっても、例えば指定管理者制度をとっている場所というのは区の施設で、要は公の施設について公のお金がおりていて、その事業ということですから、単なる単発の、たまたま物品を購入してお金が入ったというのとはまたちょっと違っていると思うんですね。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日いただいた資料の４のところのモニタリング・評価の実施状況という流れからすると、まず指定管理者のセルフモニタリングを受けて、所管課の評価の実施、総括シートをつくって、事業部経営会議で検証するということで、その後、委員会に報告があって、各委員会で総括シートの検討をしたと思うんですけれども、この流れからして、所管課の評価のところと検証が。","respondent":"堀越行財政改革担当課長","answer":"重立ったところで言いますと、総括シートを作成するときの基準ですとか、そういったものはどういうものがあるのかですとか、あとはいろいろな総括シートをつくるまでの検討の状況がどうだったですとか、これをどのような形で次年度に反映していくのかですとか。","voiceIndex":129,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"私も細かくはできませんけれども、委員会の中で出されていた中身からすると、どちらかというと指定管理者の側から出てきたものを、受けとめているだけとは言いませんけれども、そこの評価の深まっているところが見えてこないんですね。それから６２施設ですよね。その辺、とてもこの状況では議会での判断はできかねると思うので、もっともっと資料の提供が必要であると思うんですが、いかがでしょうか。","respondent":"堀越行財政改革担当課長","answer":"ただおおむね良好な管理が行われていると。それと問題点、改善事項についても、指定管理者のほうから自分でしっかりと認識をして、こういう形にしていくという報告が上がってきておりますので、そういう部分も含めておおむね良好に管理をされていると、そういうものです。","voiceIndex":131,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろ改善点はあると思います。改善を重ねていただきたいのと、あと資料に関しては、いろいろわかりやすくという、もちろんそうであると思うんですけれども、より透明性を高めるという意味では、議会が求めているものをきちんと出していただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-063"},{"speaker":"武内委員","kind":"質問","question":"前に、８３施設で指定管理者が実施されていると伺ったんですけれども、今、６２施設のモニタリング・評価なんですけれども、残りはこれからやるんですか。それとも何か理由があってやらないのか、その辺をまず教えてください。","respondent":"堀越行財政改革担当課長","answer":"ですから、今年の同様の時期に、今度は８３施設という形で評価を行って、また同様にそれぞれ所管の委員会にご報告をするという予定でおります。","voiceIndex":134,"id":"exchange-064"},{"speaker":"武内委員","kind":"質問","question":"それと家賃の収納の率だとか、収納の金額だとかが出ていて、例えば前年度よりも家賃の収納の金額が増えたにもかかわらず、この委託料みたいなものが減っている場合もあるんですけれども、これは先ほど企画部長がおっしゃった、いわゆるモチベーションを高める上での区と指定管理者の業者との間で、いろいろな取り交わしというかインセンティブみたいなものと、その半面。","respondent":"堀越行財政改革担当課長","answer":"ただ実際は所管に確認して、また後ほどご回答させていただければと思います。","voiceIndex":136,"id":"exchange-065"},{"speaker":"武内委員","kind":"質問","question":"今、一部の例だけ見ていて、多分そういうことなんだなと思ったので一応あれしたんですが、ただ年何回か指定管理者の業者と区といろいろなことで話し合いをされると思うんですけれども、これを導入した以上は、サービスの向上につながる意味ではモチベーションを上げていかなきゃいけないし、そういった感じでインセンティブを与えていくということも１つの方策でいいと思うんですけれども、場合によっては。","respondent":"堀越行財政改革担当課長","answer":"もちろん施設を管理運営していただく上で、適度な緊張関係にあるべきとは思いますけれども、信賞必罰みたいな形じゃなくて、コミュニケーションをとりながら、よりよい施設の運営を目指していくというのを基本姿勢としておりますので、そういう意味では。","voiceIndex":138,"id":"exchange-066"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"林委員","kind":"質問","question":"特別委員会ですから、いろいろな議論が出たことを集約し、あるいは出なかったことでも、ぜひ改善あるいは念を押しておきたいというこの委員会のメンバーの中の思いを、提言という形で、まとめというと、この資料でもうまとめになるわけ。こういう意見が出ましたよというのはまとめになっちゃう。それは特別委員会の１つの役目だと僕は思うんですね。ですから、あと２回ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-067"},{"speaker":"林委員","kind":"質問・要望","question":"３月はないのか。そういう集約をしていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-068"},{"speaker":"中塚委員","kind":"提案","question":"は自由闊達にということなので。ただ行政に対していろいろ私も提案したいものがあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-069"},{"speaker":"武内委員","kind":"意見","question":"私も提言をまとめていく方向でいいと思います。その上で進め方はまたちょっと案をお示しいただければ、それを会派で１回まとめたものを出し合って、それを正副委員長でまとめていただいたのを示していただいて、そこから今、中塚委員が言ったように、どうするこうする、これはどうするとなるのかちょっとわかりませんけれども、そういう方向でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":149,"id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"提言をまとめる方向ならば、それぞれがこういう点はまとめたほうがいいじゃないかという中身を出し合ったほうが、議論としては進めやすいんじゃないかと思うんですね。私としては、滞納の話も本委員会の中で出ましたけれども、滞納者の暮らしの実態なんかはぜひ、今、国保のほうではいろいろ調査していますけれども、住民税とか介護保険料のほうはなかなかそういうデータ的なものがないですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-071"},{"speaker":"林委員","kind":"意見","question":"今、委員長がどういう方向でこの委員会の終末を迎えるかという話をしているわけで、じゃ、提言をまとめたらいいですよという話をしているわけ。提言を私たちはつくるという方向でいくという委員会の意思があれば、次のステップで、例えば、じゃ、今月いっぱい、あるいは３月いっぱい、あるいは３月の半ばまでに委員長あてに各会派で提言すべき項目について出してください。そういうようなやり方もある。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":151,"id":"exchange-072"},{"speaker":"阿部委員","kind":"質問","question":"その際、ある程度文書で出していくことも技術的に必要とは思うんですが、この意見項目のほうもなかなか簡潔によくできていて、もちろん文書で出していって、その中では議題に入っていなかったことも絶対だめだというつもりはないんですけれども、やっぱり１年間やってきたこの議論というのがベースになった提言であるべきだとは思いますので、そこら辺は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問","question":"やっぱりある一定のところから論議が深まらないとこの方向にはならないので、これから先の２回がとても重要であるんですけれども、今までのところをベースにしながらも、議論を深めて方向が出せるんだったら出していくし、もしまとまらなかったときはどうするのかというあたりも、あわせて議論をしていくことが必要であると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-074"},{"speaker":"市川委員","kind":"意見","question":"やり方については、あと２回の中で委員同士の議論を深めるか、また会派ごとにまとめたものを委員長のほうに提出して、それをベースにまたここで議論をするとか、やり方についてはどのようにするのかまたここで決めればいいと思いますけれども、一応提言を出していくという方向でいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-075"},{"speaker":"阿部委員","kind":"提案","question":"しかしそれはそれとして、小粒であっても、いろいろな具体的な改善提案みたいなのは確かにあったと思いますので、それをまとめるというのもまた１つの提言と思いますので、やはりここは提言をまとめるという形で合意を持って進んでいったほうがいいんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":51174,"voices":162}},{"id":"h20-20080228-16","meetingId":"h20-cm02","date":"2008年2月28日","dateIso":"2008-02-28","committee":"街づくり特別委員会","time":"午後１０時０２分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２０年請願第４号 八潮南小学校、八潮南中学校の跡に特別養護老人ホーム建設を求める請願","agenda":"平成２０年請願第４号 八潮南小学校、八潮南中学校の跡に特別養護老人ホーム建設を求める請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"そういう形の中で、今、この請願が出てきたということで、なおかつこの委員会には紹介議員の方がいらっしゃるということでありますので、まず紹介議員の方にこの会の、八潮南小と八潮南中の跡地に特養ホームの建設を願う会ということでありますけれども、地域での位置づけはどういう位置づけとご理解をされて紹介議員になられたのか、あとは、もちろん紹介議員で署名をされたということでありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"こういう書面があることを知っていたか、たしかそんな中身だったと思いますけれども、それについてどういうふうに思っておられるのかということで、多分そういうふうな趣旨で質問されたと思うんですけれども、そこの質問をしたいと思った発想というのはどういうことだったのかなというようなことを私も知りたかったので伺いたいと思いましたから、あわせてそれもお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、そういう形の中で、ここにも書いてあるように、いろいろ高齢者の方々の中で、今、ここのは５つぐらい書いてある、さまざまな意見が出ているということは、それはもちろん地域のご意見だから、それはそれで結構ですし、今、八潮まちづくり検討委員会でされていることだから、それは構わないけれども、ここに、今この時期に、このときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"それで品川全体としても、今、特別養護老人ホームが非常に不足していると、需要になかなかこたえ切れていないという実態がありますので、八潮のところの学校という跡地利用を検討する、そこに乗せてほしいと思うのは、これは住民として、住民感情としては自然なことだと思いますから、私は何も違和感を感じずに、そうですか、わかりましたということで署名をさせていただきましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"なおかつその方が４名、こういうことで名前があるということであったら、この八潮南小と八潮南中の跡地に特養ホームの建設を願う会の方々にとっても、政争の具としてとらえられてしまう、そういうことも考えるべきだったんだろうと私は思っておりますし、なぜこういう形の中で署名をしてきたのか、そういうことを考えれば、地域の方々の努力を無にするようなことであって、そういうことをするというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"私は地域に住んでいる方たちの、その団体、会を立ち上げてつくってこられたということで、同じ地域に住んでいる者として、しかも八潮まちづくり検討委員会の中で特別養護老人ホームをつくってほしいという要求もあるということを承知した上で署名を紹介議員としてしているわけですから、全然相反しているとは思っておりませんので、そんなご発言で私に問われても、私としては非常に判断というか、困ります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは委員長にお願いをしますが、今、ご自分がどういう立場でこの委員会に参加をされているかということをご理解されていない。紹介議員の委員会出席、会議規則もあるわけでありまして、紹介議員になっている方は、説明を求められれば、それに答えなくてはならないということがあるわけです。人にこういうふうに聞く話と場が違うということだけは委員長によくお願いをして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"紹介議員として聞いたんだということは最終的な場面でわかりましたので、それは理解いたしました。私は質問をする前に、先ほど質問したことを改めて伺いたいんですけれども、今日の午前中の最後の場面で石田委員が会長にお尋ねになった、そこの真意というのを一言伺っておきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"大前提のところでおっしゃったから、一番最初に伺っておきたいということで質問します。年間にすると２回ほど募集を持たれるようですけれども、１回の募集につき何人ぐらい応募されているのか、そして何人ぐらい入所可能になっているのか、その辺の具体的な中身についても、審査の関係上、当然かかわってくることですので、ぜひ伺わせていただきたいと思いますので答弁をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"それは委員長のご配慮ですから、我々がどうのこうの言える話ではありません。しかしながら、この請願は街づくり特別委員会で扱われるという話でありますので、今のお話は厚生委員会の話でありまして、それはぜひ仕分けをしていただかないと、話がおかしくなるので、それは委員長としてよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"そうであってはならないわけです。ですからその辺については委員長としてもぜひはからっていただきたいと思いますし、そういう必要性があると判断されたので、正副委員長のところでオブザーバーとして担当の理事者に来ていただいていると私は理解しておりますので、ぜひ質問を続けさせていただきたいと思いますし、そういう妨害する発言は明確に切っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"だから私は、先ほども言いましたように、街づくり特別委員会としてこれを審査するあれにあたって、特別養護老人ホームがどうしても必要なのかどうかという、そこも含めて、あの地域にそういう施設をつくることが必要なのかということも含めて検討するにあたって、必要のない施設をつくるのは、これは税金のむだ遣いですから、必要かどうかということを審査するにあたって、品川区の現状がどうなっているのか。","respondent":"山路委員長","answer":"制限というよりも、この中身は八潮に特別養護老人ホームをという請願ですよね。そういう角度で聞いていただければお答えしていただけると思うんですけれども、特別養護老人ホームとなりますと、厚生委員会に入ってきますよね。そこら辺の区分けが。","voiceIndex":23,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"そうしたら、例えばこれは特別養護老人ホームの建設を求める請願ですけれども、例えば、アリーナをつくってくれという先ほどの午前中のまちの方々のご意見もありましたよね。そういう問題がもし出たときには、品川区の体育館の状況とか、そういうことはここでは議論できないんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その話は、委員長としてちゃんと仕切りをしていただかないといけないのは、ここは街づくり特別委員会でありまして、これは議会運営委員会というところがあって、議会運営委員会の中で仕切りを決めたわけですから、それで委員長にお願いをして、委員長のご配慮でしっかり答弁をされる方も配慮していただいたわけですから、今の話はまさにここでやる話ではなくて、議会運営委員会の中でやる話ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"八潮のまちづくりにあたって、特別養護老人ホームはまちの皆さんの要望としても出ておりますよね。そういう点で、八潮の学校の跡地利用については、特別養護老人ホームをつくることはまちの皆さんの要望でもあると思っているんですけれども、それに対して区の認識というのはどういうふうになっているんでしょうか。こういう質問ならいいんですか。答弁をお願いします。","respondent":"蓼沼高齢福祉課長、日下部企画財政課長","answer":"特別養護老人ホームに関するお尋ねですけれども、区の考え方は、これまでも再三申し上げてきましたけれども、特別養護老人ホームについては一定の水準にあるということで。委員長、大変申しわけございません。もう一度ご質問を改めてご確認をさせていただければと思います。","voiceIndex":28,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"何か本当にひどいなと思います。委員会運営そのものも、理事者の対応も。私が質問をしたのは、八潮のまちづくりの中で、まちの中では特別養護老人ホームをつくってほしいという要望があったということは、午前中、確認してきましたよね。それで、八潮の中にそういう住民の方々のご要望もあるというふうなことについては、区としてはどういうふうに認識しているのかという質問をしたつもりです。","respondent":"日下部企画財政課長","answer":"さっきも申し上げましたが、これから地域にあの案を、今日の議会に対して、地域に提案する前に、今日のこのご視察があるということで、たしかああいう形で配布をされたわけでありますけれども、いずれにしろ、これから地域の意見を募る、まさしくパブリックコメントをやろう、で。","voiceIndex":31,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"たしかこの請願が出されたのは２月１４日の日付ですよね。それで、今日いただいた「会報八潮」では、明日配布するとたしかおっしゃっていましたよね。ですからそごが出ても、これはタイム……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"それと特別養護老人ホームは、先ほどの担当課長のお話では一定の水準にあるというふうなお話でしたけれども、確かに一定の水準にはなっているかもしれないけれども、今の住民の要求からしてみれば決して十分ではないと私は思っているんですけれども、そういう点で、この請願を出されたときに、今の品川区に５７２床。","respondent":"日下部企画財政課長","answer":"１点目で区側としての見解は先延ばしというお話がございましたけれども、これは以前にも当委員会で、区側としての今後の八潮のまちづくりについての考え方ということでご説明させていただきましたけれども、やはり地域の声をしっかり受けとめる、受けとめた上で、区側として。","voiceIndex":34,"id":"exchange-018"},{"speaker":"南委員","kind":"確認","question":"ちょっと角度を変えて聞きたいと思います。そして４００人、入所率というのは計算すると１５％程度だと思うんですけれども、それでいいのかどうか、今日は担当課長がおいでになっているので、その点について伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"そのうちの入所されている方は、区内の特別養護老人ホームですと、１回の入所調整で６０名程度、ですから年間１２０名ぐらい、そのほか区外の契約施設等も含めますと、さらに１４０名、１５０名ぐらいの方が年間で入所されているという状況です。","voiceIndex":36,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"私が計算したところによると、年間１２０名入ったとして、４００人から４５０人応募されると１５％ぐらいになるのかなと思ったんですけれども、正しいのかどうか、あるいは違かったら、正しい数字を教えていただきたいと思います。入所率を聞いています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-020"},{"speaker":"南委員","kind":"確認","question":"改めて確認したいんですけれども、ぜひこの請願にこたえる、あるいは先ほど日下部課長もおっしゃったように、まちの方々の提言を受けて、それを議会とそのほかの方々のいろいろなセクションでの検討、意見を斟酌して、どういうふうな方向にしていこうかということであり、提言そのものが１００％反映されていくものではないというふうな、それはそれとして承知しております。","respondent":"蓼沼高齢福祉課長","answer":"その延べ人数ですとか率というのは、特にそこにどういう意味があるのかなと考えますけれども、ですから例えばその４００人、４５０人がお申し込みになっても、状態像はさまざまですから、ただその数に対して何人入ったかという率で。","voiceIndex":41,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"次へ行きたいと思いますけれども、再申し込みであろうと、新規の申し込みであろうと、特別養護老人ホームに入りたいという意思を持って応募されるわけですから、必要のある人だと見ていいんじゃないかなと私は思ったんです。したがって、毎回のように４００人から４５０人が応募されるという、この数字は、私はすごく重たい数字だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この請願に沿ってお話をしたいと思います。始めにお伺いしたいのは、それは八潮で今、５つの部分が書いてありますけれども、把握をしているだけで結構ですので、八潮の中の場所、規模、もしこれはわからなかったらごめんなさい。障害者の部分も含めてわかるのであれば、どういうものがあって、どういう規模のものが八潮の中にあるかということがわかれば教えていただきたい。","respondent":"日下部企画財政課長","answer":"さらにリハビリ施設ということで、たしか独立はしておりませんが、たしか特別養護老人ホームの中にも一定のリハビリ的な機能を持った、ある程度のそういう機能も多少は付加されていると承知をしています。","voiceIndex":44,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで、今言ったように、規模も言っていただければよかったけれども、品福だってそんなに、今、いろいろなものも入って使っているから、広いかというとそうでもないわけでありまして、もし八潮のまちをこれから考えていくのであれば、障害者の部分も、いろいろほかの部分も含めて、そういう部分を拡大できるような部分だって相当あるわけで、その拡大する部分の違う部分を八潮南小学校とかに持っていけば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"１つは、この八潮南小と八潮南中の跡地に特養ホームの建設を願う会ですが、八潮南小と八潮南中の跡地に特養ホームの建設を願う会という方たちはまちづくり検討委員会の存在を知っておられたのかなと、知らなかったのかなというところ、もしも知っているということであるならば、いろいろな情報交換というんですか、八潮まちづくり検討委員会ともできたのではないかなと、今日の会長のお話ですと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"ですから全然かからない方から、最高でも、ここに書いてあるように国民年金でも入れるということは６万、７万円程度で入ることが可能な施設です。ですから料金設定はさまざまです。ですからそれ以下で十分可能だということです。ですからほかの委員もそういうことで誤解されているのであれば、それは違うということで理解していただければいいんじゃないかなと思います。その点をさっき聞きたかったんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほど国民年金の６万、７万円というのが、これからどんどんでき上がっても可能なのかどうか、それが果たして国民の、利用者のニーズに合っているのかどうか、例えば個室になってくると、やはり六、七万円では入れないと思うんです。ですからその辺はどういう形で今後なっていくのか、品川区が今後どういうふうな考え方で検討をしていこうとされているのかを教えていただきたいです。","respondent":"蓼沼高齢福祉課長","answer":"ですので、それは今のところは、例えば補助にしても、個室でしか認めないと国はしているんですけれども、そういうような隘路がありますので、特に東京とか、都市部等においては、東京都もその辺については何らかの検討をする余地があるなという状況ではあります。","voiceIndex":49,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"内容に関しても、何度も説明がありましたけれども、八潮まちづくり検討委員会の中にも特別養護老人ホームというのが入っていましたし、以前の街づくり特別委員会の資料でいただきました６月６日の資料の中でも、品川区の世論調査、平成１８年の八潮編というものが紹介されていましたけれども、そこでも介護保険について、「あなたが高齢になったとき望む介護は何ですか」という質問に対して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-028"},{"speaker":"須貝委員","kind":"提案","question":"そういうふうに今、一生懸命されている中で、この街づくり特別委員会で、これをどうするんだ、こうするんだということを今決めるべきではないんじゃないかと、それならばもうちょっと経緯を見て、ちゃんと八潮まちづくり検討委員会がきちんとしたものを出して、そして改めて今回の請願について議論すべきじゃないんでしょうかと私は考えます。一応、意見だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-029"},{"speaker":"山元委員","kind":"意見","question":"今、須貝委員もおっしゃっていましたけれども、去年からずっとこの八潮まちづくり検討委員会を開催してきたわけですよね。本当にここまでやってきて、変な言い方ですが、水を差すというか、そういうのはいかがなものなのかなと思います。そういう意味では、これに対して反対、賛成とかいうよりも、しっかりともう少し見守りながら結論を出すべきじゃないかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"別に取り扱いに進んでいいんですけれども、例えば今、山元委員が発言されたところで、水を差すというところは、例えばどういうところでご自分は水を差すと思うと、ちょっとそこの見解を表明していただかないと、なかなか判断がつかないので、ちょっとそれは山元委員に伺いたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"意見交換していいわけでしょう。委員会ですから、質疑だけじゃなくて……。だからぜひ私は伺いたいなと思ったので、で、判断の材料にしたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"本当にしっかり今までずっとやっていらっしゃったことに対して、今回のこの請願に対して賛成とか反対とかと、その中身に対してではないんですが、せっかくここまでやっていらっしゃった自治会の方たちに対して、やはりこの意見を出すのではなく、まずはある程度、３月、４月ですか、まとまるわけですから、そこからまた改めて考えてもいいのではないかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"わかりました。ただ、この請願は、八潮まちづくり検討委員会の方々の導こうとしている方向と相反しているものでもなく、むしろその項目の１つと全く同じなわけです。そこのところの認識というのはきちんと押さえておかなきゃいけないと思いますので、あえて質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"あんまりそこまでおっしゃるなら、先ほど来、もう一回紹介議員の立場でお伺いしますけれども、この会の方々は、皆さん、多分知っているから、全員知っているというお話もあったけれども、その八潮まちづくり検討委員会があることがわかっていらっしゃる、その中で、それじゃあ、八潮まちづくり検討委員会の中でこういう意見を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"率直に言うとして、そういうふうな角度からの話はしていません。しかし、先ほども質問があったように、この会の方は八潮まちづくり検討委員会の存在は承知していらっしゃると思います。権利としてできると思うから、それはそれとして了解したところです。ですから私は何も違和感は感じなかったんです。で、紹介議員にも当然なりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-036"},{"speaker":"本多委員","kind":"質問・要望","question":"今まさに地域の意見をしっかりとまとめられている状況でありますから、今の時期に特定の意見だけをという段階ではないわけですから、例えばこれは特別養護老人ホームだけのことを言っているわけじゃないんですよね。５つの、何個も項目があって、それだけということではとても願意に添いがたいという、本当に地域の実情に合った区政を進めていただくために、今日結論を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-037"},{"speaker":"浅野委員","kind":"提案","question":"その理由といたしまして、やはり午前中も伺いました。そういう意味で、今回の八潮まちづくり検討委員会の流れに沿った動きで、このまま進めていただき、本当に地域の住民の皆様のいい意見をぜひとも区に提案をしていただいて、そしてまた区もそれに基づいて、さまざまなこれからの検討の糧というんでしょうか、そういうものにしていっていただければと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-038"},{"speaker":"南委員","kind":"意見","question":"しかし、八潮まちづくり検討委員会の皆さんが３月１０日までにまちの意見を聴取すると、それの先に出してはいけないんじゃないかというご意見が結構ありますけれども、本当にそういうふうに思うのであれば、この扱いは継続という選択だってあり得るわけですよね。しかし皆さんが、２会派ですけれども、結論を今日出そうということであれば、それはそれで結構だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-039"},{"speaker":"稲川委員","kind":"提案","question":"理由は、やはり今まで理事者からのお話だけで私は聞いていたんですが、今日は初めて八潮まちづくり検討委員会の会長を含めて、お会いして、その情熱が非常に伝わってきて、品川区に提案をする、その提言のたたき台を今、素案を検討して、これからいろいろ考えていくというふうに、さまざまな項目も挙がってきていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほども申し上げましたが、せっかく八潮まちづくり検討委員会が八潮のまちづくり全体について今、検討中のところに、当委員会が何らかの意見なり、今、そういう影響を、わずかですが与えるとか、そういうことは僕はあってはいけないかと思いますので、私は継続とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"今日結論を出していただきたいと思います。１つ残念なのは、先ほど私が質問したことの中で、八潮南小と八潮南中の跡地に特養ホームの建設を願う会の方たちがその存在を知っていたということをお聞きしました。ただ、やはり地元ということだけではなくて、全体を見てみんなでやっていくという、それが地域の強さになってくると思いますので、そういう意味では非常に残念なものだったなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"先ほど来ちょっと申し上げましたけれども、皆さんの今日結論を出すという大方の方々の意見というのは、３月１０日のまちの方たちの意見を尊重するんだというお話でした。そこをどう言うのかということは私は一人ひとりに伺いたかったんですけれども、その表明がなかったので、これからの会派の方々には、ぜひそこは表明をしていただきたいと思います。聞きたいと思います。ぜひ採択をするべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-043"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２点ほど確認と質問なんですが、生活関連地区のところを変えるということなんですけれども、制限あるいは緩和、具体的な内容については今後、固めていくという話だったんですが、現在、区としてはどういうものを考えているのかというのがあれば教えていただきたいのと、あと生活関連地区Ｃのほうが、これは今回、学校用地とは違うんですけれども、これはどのような制限の緩和が行われるんでしょうか。","respondent":"青木都市開発課長、日下部企画財政課長","answer":"生活関連地区につきましては、まだ具体的に、まさにご議論いただいている最中で、先ほどの別件でしたけれども、企画財政課長からのご説明としても。生活関連地区Ａですけれども、これは以前も当委員会にご報告しています。八潮北小学校の跡を明晴学園、それからマイスクール八潮で活用する、これが一応、基本的な方向性として明らかにしているものです。","voiceIndex":81,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと具体的な何を施設に入れるかというものではなくて、以前ありましたけれども、縛りが厳しいというような、一団地の住宅施設という都市計画から、わりとなだらかな地区計画に移行していくという話だったので、具体的な、もちろんどういうものを入れていくかというのはこれから住民、地元のところで大いに議論されているところなので、それはもちろんそれでいいんですが。","respondent":"青木都市開発課長","answer":"一団地の住宅施設は都市計画で定めたもので、この環境を守るためにつくられたものですから、現在の環境を守るために何らかの違う制度に置きかえて、より運用しやすくしていこうというのが今回のご報告しています都市計画手続でございまして、その手段としては。","voiceIndex":84,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"ざっとで、概要で結構ですので、一団地の指定があって、それを地区計画に変えたという経緯ですね、非常に大変な作業だという認識を私は持っているので、これは簡単にできるものなのか、そういうのはいろいろ諸交渉があって、そこが実現したということなのか、どのぐらいの流れがあったのかということについてお伺いしたいと思います。","respondent":"青木都市開発課長","answer":"ただ、八潮団地のような場合はちょっと例外的で、ほかの団地では住宅自体の老朽化に伴って団地全体をリニューアルしていこう、建て替えていこうという中で新たなまちのあり方というのを議論した、そういった建て替えを契機に地区計画に移行する事例が多かったんですけれども。","voiceIndex":86,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"そうするとかなり新しいことを、制度を取り入れたということなので、品川区としては成功なんでしょうね。成功の要因って何だったのかなと思うんですけれども、そこら辺の、東京都が先ほどかなりバックアップしてくれたという話なんですが、要因というのは何かあるんでしょうか。","respondent":"青木都市開発課長","answer":"要因というのは難しい言い方になりますけれども、時代をうまくとらえたということ、あともう１つは住民の方々の、まさに午前中にもご懇談いただいたような方々の動きがあって、自分たちで住宅、団地のあり方を考えていこうといったことがあることは。","voiceIndex":88,"id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど言ったブロックごとにいくと、現在のままでいくと、とりあえず建て替えまでは容積率、建ぺい率を変えないということだから、一時的には既存不適格になるところも出てくるという理解でいいのか、だけどそれはそのままではないから、建て替えとかがあったときにはちゃんと直しますよという意味でとらえておけばいいのか、そこら辺の点を教えていただきたいのと。","respondent":"青木都市開発課長","answer":"地区計画制度というのは中身の変更というのは可能な制度ですので、またそれはご議論、地元での熟度の高まり等を踏まえて、必要に応じて地区計画制度の運用を図っていくことで対応できると考えております。","voiceIndex":90,"id":"exchange-048"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最後の部分、今度は地区計画に変えるのでしようがないんでしょうが、ぜひその次の、どうしてもこういう品川区全体のことを考えていけば、もちろん地域の方々がこれだけなさってくださっているところもあるわけだけれども、やはり聞ける部分と政策的な部分も必ず出てくるんだろうから、そうなってきたときに、政策的な部分を今後こういうふうにしようといったときに、地区計画になった後でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"１つは今後の流れというところの具体的なスケジュール、いつぐらいまでに、どこのレベルまで、どういうふうに行くかというスケジュールを知りたいことと、それから八潮の地域は第１種住居地域ということで、一定程度建物が、これはだめだよという制限があるところなんですけれども、スポーツ施設ですか、結構、この間も地域の声として挙げられている、そういうものなんですが。","respondent":"青木都市開発課長","answer":"ですので小学校、中学校、どちらをとりましても床面積３,０００m2を超えておりますので、これがアリーナのほかに教室の部分を転用して、例えば卓球場に使うとか、ジムに使うとかというような形でのスポーツセンターというような形になりますと。","voiceIndex":93,"id":"exchange-050"},{"speaker":"南委員","kind":"意見","question":"聞き逃していたらあれなんですけれども、１６ページのところでみどり率という説明がありましたよね。東京都が２０１５年までに３２％という決定はわかったんですけれども、これに基づいて、品川区も当然、みどり率というものの具体的な目標をつくるんですよね。どういうふうに設定しようとしているのか、改めて。","respondent":"松代管理工事課長","answer":"これまでそういう形でやってきたんですが、先ほど申しましたように、区民の方にはなかなかそれが、数値が実感としておわかりいただけないと、そういったところで、何か区民の方に今後、いろいろな形でご参加していただくときに、みどりに関心を持っていただき。","voiceIndex":99,"id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"今はなくて、こういう面積を改めてピックアップして計算して出すということはわかったんですけれども、１０年、１５年後ということじゃなくて、やっぱり直近の、できるだけ早い時期にそのみどり率というのを、現状をしっかり出して、そして近い将来、どこまで到達するかというのを、東京都が３２％なんですけれども、それに見合って出したほうがいいのか。","respondent":"松代管理工事課長","answer":"今回のこの構想の中で、できればお示し等をここでと考えていますし、場合によっては、今まさに区の方針として、基本構想を定め、基本計画、次に実施計画という形でやっておりますが、それを定めている最中ですので、そういう中できちんととらえていくほうがいいのか。","voiceIndex":101,"id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"わかりました。どの程度のみどり率が一番望ましい環境基準になるかというのはちょっと私もわからないところですけれども、外国の先進の都市の状況なども見たりとか、そういうのをして自分自身も調査研究していきたいとは思っているんですけれども、そういう高い数値目標をできるだけ持つように、そしてそこに進んでいけるようにしていくべきだということを思うわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと気になった点で、１０ページから１１ページなんですけれども、物と大規模施設の重視から「人」と「小さな試み」へということでありますけれども、あとは緑被率の推移のところもありましたが、「地上部で確保できるみどりの総量には限界があるため、今後は建築物の屋上や壁面・河川の護岸などの新たなスペースの緑化を行うなど」というような表現もあるんですが。","respondent":"松代管理工事課長","answer":"当然のことながら、今後も、みどり率にかわったとしても、みどりを増やしていくハード面のほうには、我々としましては、あらゆるときにそういったようなもの、公園も含めまして、みどりを増やすような努力をしていきたいと考えているところですので、その点については。","voiceIndex":104,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと関連して素朴な疑問がありまして、６ページのところの緑被率の上昇のところでグラフ等がありますけれども、１９９４年から１９９９年までの５年間と、１９９９年から２００４年までの５年間、同じ５年間なんですけれども、後半が伸びが０.７％となかなか厳しい状況にはなってきているのかなと感じましたけれども。","respondent":"藤田道路公園課長","answer":"特に後半の５年にわたっては、先ほど委員からもお話がありましたとおり、新たな緑化の場所の創出ということで、屋上緑化でありますとか、あるいは壁面の緑化、そういったものも活用しながら、さまざまな形で駆使しながらやってきておりますので。","voiceIndex":106,"id":"exchange-055"},{"speaker":"須貝委員","kind":"意見","question":"すばらしいことだと思うんですが、ただ、河川というのは上流、中流、下流とありまして、やっぱりそれに関係する他の自治体との連携というのがかなり今後重要視されるのかなと、品川区のところの河川だけという話じゃなくなってくると思うので、ここまで品川区がきちんと基本方針というものを出してくるとなると、その辺についてはどのように今後対応していくというか、他の自治体。","respondent":"家壽田下水道河川課長","answer":"ただ、要望だけでは大変問題ですので、我々流域の区としては、例えば目黒区、それから世田谷区と目黒川流域の３区の連絡会、昔の３区連合というもので、それでいろいろな議論をしておりまして、当区で行っている水質改善の検討なんかの情報交換、意見交換もやっておりまして。","voiceIndex":108,"id":"exchange-056"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望だけなんですが、品川区がこれだけ取り組んで実績を上げられているわけですから、ぜひとも何度も何度も他の自治体にも要望していただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-057"},{"speaker":"石田（秀）委員","kind":"質問","question":"この新・水とみどりのネットワーク構想の原案で、概要版で結構なんですけれども、これは、どういうつもりでというか、どういう形でといったらいいか、書かれたのか、例えば何かを支援しますよ、まちはどういう位置づけで、こういうことを創造します、創出します、支援します、これをずっと見ていくと、そういうことが書かれ出すのは第４章からかなと思うんだけれども、そういうところで。","respondent":"松代管理工事課長","answer":"それと、そういう場の提供、機会、なかなか難しいと思いますので、行政側がそういったものを積極的に支援して、それをしやすいような形をとっていって、加えて、次の話もちょっと難しいかもしれませんけれども、規制緩和とか、助成とか。","voiceIndex":111,"id":"exchange-058"},{"speaker":"石田（秀）委員","kind":"質問","question":"ここで紋切り型で、あとは頑張って連携していくというのはわかるんだけれども、もっとそういう意味合いの突っ込んで書く、こっちみたいに、こっちの言葉みたいにというんじゃないけれども、もっとわかりやすく紋切り型じゃなくて書くべきだったんじゃないのかなというか、書いたほうがいいんじゃないのかなと思うんだけれども、そこら辺をそうしなかった理由というのを教えてください。","respondent":"松代管理工事課長","answer":"ちょっと誤解のないようにお話ししますが、今、進めている区の計画、基本構想、今後、定められる長期基本計画、それに基づいた実際の実施計画、これが行政の基本です。その中に個別計画として今回の構想と、これはみどりの分野としての計画を論じていきます。","voiceIndex":113,"id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"意見","question":"お願いだけしておきます。これから長期基本計画がまた議論をされていくわけでありますから、あれだけの基本構想が出てくれば、長期基本計画は踏み込まざるを得ないんだろうなと思っています。この前の職員報を読ませていただいたけれども、５つの分科会の方々も結構踏み込んでいるし、そう考えると、長期基本計画は必ず踏み込んでいかざるを得ないだろうなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6360#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":48524,"voices":121}},{"id":"h20-20080303-3","meetingId":"h20-c-budget","date":"2008年3月3日","dateIso":"2008-03-03","committee":"予算特別委員会","time":"午前１０時０２分～午後６時２０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を162件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"浅野副委員長","kind":"質問・要望","question":"第１項、理事および理事会の設置についてです。閉会予定時間は、区役所の執務時間と同じく午後５時１５分を目途といたします。１人あたりの質問時間は、答弁時間も含めて１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"おはようあります。トップバーターであります。私は、６１ページの近隣セキュリティシステム運営経費、それから、６９ページ、子どもすこやか医療費助成事業追加分、それから、５９ページの雑入の財団法人特別区協議会配分金について伺います。清掃一部事務組合だけは人口割だと思いますけれども、この負担金の中で、今言った四つは２３区一緒という理解でいいのかだけ、ちょっと先に教えていただきたい。","respondent":"田中区民生活事業部長、諸岡児童課長、桑村総務課長","answer":"結果として、３月１日から事業譲渡ということで、無理なく子どもたちの安全が守られたと考えております。前半は、今申し上げましたように、予算どおりの執行でございましたが、１０月、１１月時点において、その後に対しての懸念材料が幾つか出てまいりました。歳入のほうですけれども、特別区協議会の配分金ですけれども、総会等によって決めたわけですけれども、別館をつくるときの分担等につきましては。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは、見方によっては、どうしてなんだという検証をしっかりしておくべきだろうと、私は思っております。何でかといったら、建物を建てるスケールメリット、数がいっぱいあるわけですから、よくよく考えて、火災保険をかけないで、火災になってもし建て直すんなら、自分のところで直しちゃったほうが、全体的なコストは下がるという考え方があるわけですよ。それを教えていただければと思います。","respondent":"福田企画部長、諸岡児童課長、桑村総務課長","answer":"具体的に申し上げますと、それぞれの事業部、あるいは部の中で、今回直接かかわらない問題につきましても、どういう問題があるのか。中学生までの無料化につきましては、昨年１０月から始まったばかりでありますので、この辺の推移を見ながら、今後、検証を加えていきたいと考えています。そういったものの研究等をさせていただいて、その意味で、どういう形で入れば一番安く、また。","voiceIndex":13,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"答弁はもうできないでしょうけれども、子どもすこやか医療費は、そういうことを聞いたつもりではなかったんです。それの検証、どうやってこういう形になってきたのかということを、しっかり見据えてからやっていただきたいということを、再度言っておきます。それから、保険は、ぜひ見比べていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-004"},{"speaker":"金野委員","kind":"確認","question":"よろしくお願いします。５１ページの衛生費補助金でありますけれども、先ほどもご説明をいただきまして、福祉施策包括補助金の廃止とともに、ここに分配をされたという医療保健政策包括補助金、この任意予防接種費用の一部助成ほか４事業とありますけれども、まずは、この４事業のご説明を、改めて確認のためお聞きしたいと思います。","respondent":"太田健康課長","answer":"全体で５事業あります。そこに書いてあります任意予防接種費用の一部助成、そのほか飼い主のいない猫対策、それから、３点目が麻疹の緊急対策予防接種、４点目が麻疹・風疹任意予防接種、５点目が健康危機管理対策、いわゆる新型インフルエンザ対策のものです。","voiceIndex":19,"id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"その４点の中の新型インフルエンザ対策について、お伺いします。発熱センター設置運営訓練が実施をされたところですが、これは、たしか平成１７年度から実施をされているんでしょうか。そのことについて、改めてこの機会にお伺いさせていただきたいんです。お願いします。","respondent":"倉橋品川区保健所保健サービス課長","answer":"今までに実施してまいりました訓練というのは、発熱センターの設置でございましたが、今回はその運営ということで、多人数の方が受診した場合、また、スタッフだけではなく、受診者側の感染予防も考慮して、実際に運営するノウハウを蓄積するために実施したという特徴があります。","voiceIndex":21,"id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"毎年新型と言われて、私も子どもを持つ母親としては非常に心配ですし、また高齢者にとっても心配なので、新型のワクチンの確保、そのことに関しては、どのような対策なんでしょうか。","respondent":"倉橋品川区保健所保健サービス課長、太田健康課長","answer":"これにつきましては、国のほうの備蓄、それから、接種の方針がありますので、こちらの動きを見ながら慎重に対処しています。補足としてご説明します。区といたしましては、平成１７年度予算で、新型インフルエンザ対策ということで、タミフルを約３,０００人分を備蓄して、現在、品川、荏原両薬剤師会のほうに保管をお願いしています。","voiceIndex":23,"id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"そのほかの予防接種に関しては、また、平成２０年度予算で、そのときにお聞きしたいと思いますので、よろしくお願いします。次の質問で、出産育児一時金の更正減額についてですけれども、まず、２,８００万円。一時金は１人３５万円ですので、単純に計算をしますと８０人分減となるんですが、この数字の根拠というんでしょうか、年度途中ですので、どのようなことでこうなのか、教えてください。","respondent":"原国保年金課長","answer":"こういった当初予算で組んだ人数ですけれども、過去の推計をもとに、どのぐらいの出産が見込めるかということで、当初、組んだところですけれども、今年２月で４４８人ということで、おおよそ４９０人のところで推計をしています。","voiceIndex":28,"id":"exchange-008"},{"speaker":"金野委員","kind":"確認","question":"一時金の確認ですが、支払われ方、今、国民健康保険をかけていらっしゃる方が、こちらでいただくようになっているんですが、受取代理人制度というんでしょうか、平成１９年度は４月からスタートをしていると思いますが、このことの概要と、また、４月からスタートしておりますので、どれぐらいの方が利用されているのか、現状をお聞かせください。","respondent":"原国保年金課長","answer":"受取代理制度をこの４月から発足したところですけれども、現在、８２件ということで、この４４８件に対しますと１８％の方が受取代理ということで受付をしています。こういったものを多く区民の方に周知をする中で、この受取代理制度を広く進めていきたいと思っているところです。","voiceIndex":30,"id":"exchange-009"},{"speaker":"金野委員","kind":"質問","question":"とてもいい制度だと思いつつも、今、お聞きしますと、利用件数がまだ１８％ということなので、これはやはり周知がなかなかされていないという現状が、この数字にあらわれているのか。それとも、後からのほうがいいという、単純にそうだったのか。ちょっとその件数の推移から見て、周知の度合いはどうなんでしょうか。","respondent":"原国保年金課長","answer":"今後につきましても、区のほうの国民健康保険についても、いろいろな形で区民に周知する機会がありますので、さらにこういったものを広げていきたいと考えているところです。","voiceIndex":32,"id":"exchange-010"},{"speaker":"金野委員","kind":"質問・要望","question":"まだ始まったばかりなので、そういう形なのかなとも思いつつも、やはり、これだけ安心して安全に産み育てられる環境が整いつつある中ですので、どうかそこら辺の周知も、今おっしゃってくださったような形で、今後も力を入れて一層取り組まれていかれますよう要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６１ページの近隣セキュリティシステム運営経費について、お伺いをします。先ほどちょっと説明があったんですけれども、正式な場ですので、改めてこの補正が必要になった経過のご説明と、それから、５,７９０万円の内訳を教えていただきたいと思います。","respondent":"中山地域活動課長","answer":"冒頭にもご説明ありましたとおり、近隣セキュリティシステムの子機、いわゆるまもるっちの長期契約による減額の適用時期を、平成２０年１月であったにもかかわらず、年度当初の４月からと誤って当初予算を計上した、これがご説明した当初予算の計上の不足の部分です。","voiceIndex":36,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目の積算ミスのところなんですけれども、契約がプロポーザル契約だと伺っているんですが、そうだと、区が何を求めて、ＹＯＺＡＮ側がそれにどうこたえてきたのかという内容が、多分あると思うんで、ちょっと契約の中身をお聞かせいただきたいと思います。契約書を一度も見ていないので、単価契約ということなんですが、その中身、何が書かれているのか。","respondent":"中山地域活動課長","answer":"実際には、そのほかにシステムを稼働するためにデータを入力する事務手数料であるとか、番号変更の手数料等、それぞれ単価がありますけれども、月額基本料金の中で７２１円、それから、減額の基本料金として３２２円の単価の契約になっているものです。","voiceIndex":38,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"変わっているのか、ずっと同じできているのか、契約の中身と、今、ありました通信のところの１台７２１円、この辺が、どう推移をしてきているのかお聞かせいただきたい。それからもう１点は、まもるっち１台の購入価格が幾らで、どのぐらいの貸与年数なのか、ちょっとついでなので、その辺も教えていただきたいと思います。","respondent":"中山地域活動課長","answer":"これ以降の子機の基本料金に絞って申しますと、先ほど申し上げた７２１円余の月額単価というのは、当初の契約、平成１７年度以降変更はございません。現在までその額で続いているです。","voiceIndex":40,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"契約においては、当初から７２１円で変わりがないというところにおいては、平成１９年度が積算のミスで３２２円で計算して、差額が生じたというわけなんですけれども、単純なミスと受けとめていいのでしょうか。その点が一つ。それから、どういうチェック体制が行われていたのかということと、今後の防止対策をきちんとお示しいただきたいと思うんですが、その点をお願いします。","respondent":"中山地域活動課長","answer":"したがって、そういう面では、これは今後のご質問もありましたけれども、当然、現在は、予算編成段階から、その予算額、あるいはそういう関係書類についても十分に確認していくという形で考えているものです。","voiceIndex":42,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと調べたら、２００５年当初から、ＹＯＺＡＮはいろいろな面で、ＰＨＳの撤退とか、ワイマックスとか新しいものに挑んで、結局うまくいかなくて、凍結をされているというようなところにおいては、契約段階で、実績を重んじて契約をするということもよく伺うわけですけれども、この辺、契約の段階で、どういう判断がされたのかもお聞かせください。","respondent":"福田企画部長、中山地域活動課長","answer":"これは、当面の措置でございまして、先ほど、別の委員にお答えしましたように、本格的な検討につきましては、事業部経営会議を中心として全庁的に行っていくと考えておりますが、当面、現在の措置といたしまして。ＹＯＺＡＮの経営危機の認識の時期ですけれども、ご質問にもありましたとおり、ＹＯＺＡＮの株価等の動向というのは、最高８０万円ぐらいのものが１５０円前後に下落するというような状況は、区でも把握しておりました。","voiceIndex":44,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"今のご答弁だと、１点目は、従来の今までのチェック体制がダブルチェックになっていないという認識でいいのか、もう１回、そこのところをお伺いしたい。それから、ソフトバンクの今後なんですけれども、こういった状況の中で、また値上げがされるのではないかという心配も抱いていますが、この点はいかがでしょうか。","respondent":"福田企画部長、田中区民生活事業部長","answer":"おりましたが、当時、ただそれが十全に機能しなかった、ここが我々の反省点です。したがいまして、当面の措置として、先ほど申し上げたとおり、だれが予算照合したか、このことを起案文書上明らかにしているものです。秋以降、ＹＯＺＡＮが回線を調達している会社にお金を払っていけない、滞納が蓄積していく、その結果として、回線のサービスが継続できるかどうかという危機的な状況が生まれてくる中で、１万２,０００人の児童の安全を考えた場合に。","voiceIndex":47,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まもるっちのシステムはぜひ守っていただきたいんですが、ぜひ、区民の理解を得られる説明を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-018"},{"speaker":"石田（慎）委員","kind":"意見","question":"私のほうから、６１ページの防犯拠点整備事業についてと、６３ページ、ＣＡＴＶ視聴困難地域解消対策負担金について、お聞かせください。それから、ケーブルテレビ、減額されているんですが、現在、品川区内はどこまでカバーがされているのか。なぜ減額になったのか。すべてもう解消されたから減額になったのか、それとも、まだあるけれども、何らかの理由で減額になったのか、そこをお聞かせください。","respondent":"高濱生活安全担当課長、堀越行財政改革担当課長","answer":"現状についてですけれども、本来、跡地に新たなトイレと併設した施設を建てる予定ですが、現在、それがまだ建っておりませんで、仮の施設を向かい側に建てておりまして、そこにまちの方の協力を得ながら。それに対して、区として一定の助成という形で負担をしているわけですが、今年度の場合ですと、電波障害のある地域、既存の共聴施設を、ケーブルテレビ品川のほうに切り替えていただくといった形で。","voiceIndex":52,"id":"exchange-019"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ほかの地区では、今のところ考えていないということですが、例えば、他のところでも、交番等がなくなる際には検討するのか、どうか、お聞かせいただきたい。荏原町安心安全ステーションなんですが、警察との連携だったり、町会、地域との連携というのはどのように進められているのか、お聞かせいただければと思います。","respondent":"高濱生活安全担当課長","answer":"交番がなくなると他の場所でも検討するのかというご質問についてですが、交番の統廃合につきましては、昨年度、警視庁のほうで厳密に計画をいたしまして、行いました。","voiceIndex":58,"id":"exchange-020"},{"speaker":"石田（慎）委員","kind":"意見","question":"近隣の町会、１０人程度ということなんですが、区のほうとして町会に要請というか、町会にそのまま投げて、町会のほうでボランティアを募っているのか。区としても、ほかの地域も含めて、ボランティアを募っているのかということ。例えば、どこかにホットラインのサインが載っているのかどうか、そういった整備の点をお聞かせいただければと思います。","respondent":"高濱生活安全担当課長","answer":"これを４月から１１月まで９カ月間行いまして、それを見て、町の方でも対応ができる、またもし何かあってもすぐにサポートできるという体制が整いましたので、町会長を通じまして、まちの方で滞在をしていただける方はいらっしゃいませんかという形で呼びかけを行いまして。","voiceIndex":60,"id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ホットラインの件なんですが、ハンズフリーでしゃべれるということで、それは警察署と話せるということでよろしいんでしょうか。その場合、例えば区との連携はどのようになっているのか、教えていただければと思います。","respondent":"高濱生活安全担当課長","answer":"荏原警察署とダイレクトに会話ができることになります。それがもしつながらなかった場合には１１０番、あるいは区役所の生活安全担当の窓口につながるようになっております。","voiceIndex":62,"id":"exchange-022"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ぜひ、先ほども言いましたが、ほかの地区でも進めていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-023"},{"speaker":"渡辺委員","kind":"質問","question":"よろしくお願いします。私のほうは、４９ページになります、大井第一小学校水道管直結化事業と、８５ページになります、財源更正のすまいるスクール運営費に関して、この２点、お伺いしたいと思います。大井第一小学校水道管直結化事業、この工事のあらまし、構造と、主な目的をお伺いしたいと思います。よろしくお願いします。","respondent":"市川庶務課長","answer":"この背景には、蛇口から直接おいしい水を飲むということ、それから、水道管の整備によりまして、３階程度の建物まで直接水道管から給水ができるようになったということを受けての事業です。","voiceIndex":66,"id":"exchange-024"},{"speaker":"渡辺委員","kind":"確認","question":"東京都のモデル事業ということで、安全でおいしいが主題となっているようなので、現状で、肝心の児童の飲料水をはじめ事足りている部分から、またさらに発展をというふうに、私個人としては、ご答弁からとらえたのですが、この事業に関して、設備の二重投資にならないかという点で、やはり今後の展開もあるかと思いますが、確認をしたい点が１点。","respondent":"市川庶務課長","answer":"３点目の、今後の取り組みですけれども、東京都水道局は、この事業を平成１９年度と平成２０年度ということで展開をしておりますが、平成２０年度につきましては、大井第一小学校の実績を踏まえて、今後、東京都と協議、相談をして。","voiceIndex":68,"id":"exchange-025"},{"speaker":"渡辺委員","kind":"確認","question":"いい確認ができたと思いますので、次の質問に移らせていただきます。そういう中で、先行の事例として、品川区が評価される部分が非常に多くあると考えられますが、都とのやりとり、あるいは他区から問い合わせも多々あると聞いていますが、この辺の東京都サイド等の評価、あるいは、品川区でのこれまでの取り組みの自己評価も含めて、まずお伺いしたいと思います。","respondent":"市川庶務課長","answer":"ご案内のとおり、私どものすまいるスクール事業は、品川区が進めてまいりました教育改革の一環ということで展開をしてきた背景があります。","voiceIndex":70,"id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問・要望","question":"他区での取り組みの中では、地域に丸投げしていたり、そういう中では、行政が肝心なところは責任をしっかり持たれているという点で、素人的に見比べても、十分に誇りに思える制度かなという中で、さらに発展をする中で、職員構成について、少しお伺いしたいと思います。今後、普通の制度とは異なるとは思いますが、現況と、今後の考えをお伺いしたいと思います。","respondent":"市川庶務課長","answer":"すまいるスクールの専任指導員につきましては、基本的に開設後、まだ間もないわけですけれども、少なくとも、ご指摘ございました、学校との連携、一体感、こういったことを損ねることのないような在所期間ということを念頭に置いて臨んでいきたいと考えております。","voiceIndex":72,"id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、４２ページの民生費負担金について、そして２番目に、７１ページの育児休業代替等人材派遣について、また、７３ページの保健事業費負担分の乳がん検診について質問をします。７３ページの保健事業費追加分の乳がん検診について、お伺いをさせていただきたいと思います。約１,８００万円の増は、どういう内容なのか、まず教えていただきたいと思います。","respondent":"太田健康課長","answer":"それに９月以降、適宜、回数を増にしてきたということで、その分で約１,０００人分、それから、医師会に委託しております分の約２００人増、それで約１,２００人増ということで、最終の歳出見込みが５,０５０万円余ですので。","voiceIndex":76,"id":"exchange-028"},{"speaker":"山元委員","kind":"質問・要望","question":"今、お聞きいたしましたけれども、そうしますと、乳がん検診の内容なんですけれども、具体的にどういう検診を受けられるのか。その受けられる箇所といいますか、何カ所で受けることができるのか、教えていただきたいと思います。","respondent":"太田健康課長","answer":"箇所ですけれども、マンモグラフィ検診については、品川区医師会、荏原医師会ということで、平成１９年度当初、実施してまいりましたが、先ほどご説明したとおりそこだけでのキャパシティがいっぱいになりましたので、予防医学協会の検診車を追加したです。","voiceIndex":78,"id":"exchange-029"},{"speaker":"山元委員","kind":"質問・要望","question":"品川区医師会、また荏原医師会、そして検診車の３カ所に分けて、マンモグラフィの検診ができるというご答弁だったんですが、実際、厚生労働省は４０歳以上の対象であったのが、我が品川区は３４歳以上ということで、幅が広がって、ほんとうに女性の私たちにとっては、とっても嬉しいことなんですけれども、この３カ所で、マンモグラフィの受診者、１日何人ぐらい受診されているか、もしおわかりでしたら。","respondent":"太田健康課長","answer":"月大体１０回前後で、年間で１１８回という形です。品川区医師会で１,３００人強、荏原医師会で１,７００人強という形です。それから、検診車については、１回の定員が５０人ですので、今年度については、９月以降２０回で、１,０００人分ということになっております。","voiceIndex":80,"id":"exchange-030"},{"speaker":"山元委員","kind":"質問・要望","question":"１日に２８人とか、意外に人数が少ないんだなと、実は、今びっくりしているんです。検診に当たる時間というんでしょうか、台数が少ないので２８人なのか、それとも、限定２８人までとなっているのか、その辺を教えていただきたいんです。","respondent":"太田健康課長","answer":"基本的には、品川区医師会、荏原医師会、それぞれ機械としては１台です。それで、半日単位ですけれども、許容キャパシティとして、お１人、大体３０分から４５分ぐらいかかるというようなことで、最大限できて、そういう人数ということで聞いているところです。","voiceIndex":82,"id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"よく相談されることは、なかなか電話がつながらない、やっと電話がつながったなと思えば、今度は予約がなかなか取れないという相談があります。今、お聞きすると、お１人大体３０分から４０分かかるので、１日二十数人という人数が決まってくるということですけれども、その辺、もう少し拡大する何か手だてというか、区としては、何かお考えがあるかどうか教えていただきたいと思います。","respondent":"太田健康課長","answer":"平成２０年度以降については、その検診車をさらに有効活用しながら、あとは受診者の動向等を加味しながら、検討を重ねていきたいと考えているところです。","voiceIndex":84,"id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"実は、日本の女性では、乳がんの羅患率というんでしょうか、胃がんを抜いて第１位だと聞いております。実は、これもやはりご相談の中なんですけれども、働いている女性が大変多いですよね。そうした場合に、本来であったら仕事を休んで受診しなきゃいけないと考えるんですが、そういうことでなく、何か手だてといいますか、平日以外でも、何かお考えがあるかどうか、教えていただければと思います。","respondent":"太田健康課長","answer":"はまた、医師会ですとか、予防医学協会、その辺に、土日ができるかどうかの問題もありますので、先ほどもご答弁申し上げましたが、まずは今の体制の中で希望される方について受診を優先していきたいと考えております。","voiceIndex":86,"id":"exchange-033"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、平日ということになりますと、例えば、品川区以外で受診ができないかなと思ったりいたします。その辺はいかがでしょうか。","respondent":"太田健康課長","answer":"その辺も含めて、昨年、実はいろいろな方面で検討をしたんですけれども、なかなかうまく受ける機関等も見つからなかったということで、現在の検診車になっておりますので、ご理解をいただきたいと思います。","voiceIndex":88,"id":"exchange-034"},{"speaker":"山元委員","kind":"質問・要望","question":"そういう意味では、ぜひ、１日も早く土日とか、特にお仕事をしていらっしゃる方たちにも門が開けるように、努力をしていただきたいと思います。どうぞよろしくお願いいたします。では、次に、７１ページの育児休業代替等人材派遣について、質問をします。実は、これを見て何なのかなと不思議に思いまして、大変お恥ずかしいんですが、これはどういうことなのか教えていただきたいと思います。","respondent":"小林保育課長","answer":"お尋ねのありました育児休業代替等人材派遣、この「等」のところが不明確で、申しわけないんですが、この内容は、育児休業で休む職員以外に、病気等で休む者、あるいは特別支援の児童に対応するための職員、いずれも保育士ですけれども。","voiceIndex":90,"id":"exchange-035"},{"speaker":"山元委員","kind":"質問","question":"それにいたしましても、１億何千万円の減なんですけれども、この辺の中身といいますか、内容はどういうことなんでしょうか。","respondent":"小林保育課長","answer":"その内訳といたしまして、大きいものとしては、最終的に１２１名程度見込みましたところ、実績は８３名ということで、４０名弱の人材派遣の費用相当分が減りまして、その減額の補正をお願いしています。","voiceIndex":92,"id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"ほんとうに心配だったのは、育児休業がとれなかったのではないかということでしたが、ぜひ、取れる体制をしっかりととっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-037"},{"speaker":"井桁委員","kind":"質問","question":"私は、６８ページの児童福祉総務費の各種保育事業補正追加分、それから、先ほど、他の委員からもありましたが、７３ページの乳がん検診について、お伺いしたいと思います。６８ページの児童福祉総務費の各種保育事業助成追加分で、先ほど、理事者からもありましたとおり、利用者の増とありましたが、具体的にどのような事業で利用者の増加と、事業の追加といいますか、そういったことがあったのでしょうか。","respondent":"小林保育課長","answer":"予算人数おおよそ７００人弱、６９２名を見込んで予算計上させていただきましたが、区内の認証保育所の主に０歳児の入園児数が増えたために、その分の認証保育所へ払います保育の助成額といたしまして、１,４００万円余の増額をお願いするところです。","voiceIndex":96,"id":"exchange-038"},{"speaker":"井桁委員","kind":"意見","question":"先ほどありました、認証保育所の助成ということなんですけれども、現に今、そういった保育所で、例えば区立の保育園であったりした場合に、入れなくて待機児といいますか、それの解消のために、今年、品川区では事前に申込みというのがあったんですけれども、今現在、待機児童の人数がわかればお願いいたします。","respondent":"小林保育課長","answer":"ただ、待機児数と申しますと、一定の考え方、それぞれの状況を精査して認定してまいりますので、申しわけございませんが、正確に把握して公表する数字を持ち合わせておりません。","voiceIndex":98,"id":"exchange-039"},{"speaker":"井桁委員","kind":"意見","question":"私の周りでも、子どもを産んで、１歳になったら保育園に入れたいんだけれども、やはり４月から産まれる子ども、私の周りでも、４月に全員が産まれるわけではありません。そしてまた、その児童に関して、今後、さらに４月からの新しい事業で、事前の予約というのがありましたけれども、それに関しても、今、何人ぐらいの予約件数といいますか、そういった申込みがあるのか、お願いいたします。","respondent":"小林保育課長","answer":"後段のご指摘なんですけれども、当区では、いつ入れるかわからない不安、そういった不安定感を持たずに、できるだけ、例えば１歳までとか、親子のきずなを深めていただいて、その後は、そういった不安を抱かずに職場に復帰できる制度を、ということで、来年度。","voiceIndex":100,"id":"exchange-040"},{"speaker":"井桁委員","kind":"質問","question":"７３ページの予防費の乳がん検診について、お伺いします。先ほども、他の委員からもありましたが、この乳がん検診のほかに、品川区ではさまざまな検診を、現在行っていると思うんです。今年４月からこの制度が変わることにおいて、再度改めて、どのような変更点であるとか、そういったことがあるかどうかお伺いしたいと思います。","respondent":"太田健康課長","answer":"４月から特定健診、特定保健指導ということが実施されます。これは、各医療保険者、健康保険、あるいは政府管掌保険、国民健康保険といった医療保険者が、今度、特定健診保険指導を実施するです。健診主体が、区から各医療保険者へ変更になるということが大きな点です。","voiceIndex":102,"id":"exchange-041"},{"speaker":"井桁委員","kind":"質問","question":"そうしますと、今までは対象者に対してお知らせといいますか、そういうのが届いていたと思うんですけれども、今後も、そういった告知等々のことで変化はありますでしょうか。","respondent":"太田健康課長","answer":"区民健診の分は、今申し上げたように保険特定健診に移行しますので、各医療保険者が保険者ごとに通知をしていくということになります。区民健診以外の保険については、がん健診等については、区から管掌ということでのお知らせをしていくということになります。","voiceIndex":104,"id":"exchange-042"},{"speaker":"井桁委員","kind":"質問","question":"最後に質問なんですけれども、区民健診で、平成１６年、１７年、１８年と、数字のほうが２１％、２０％とありますが、今後、そういった制度が変わる中で、増加といったことに関してどのようにお考えでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-043"},{"speaker":"菊地委員","kind":"質問","question":"私のほうも、７３ページ、生活保護費についてお聞きをしたいと思います。生活保護費で、６億２,０００万円余りの更正減額となっております。かなりの金額ですけれども、平成１８年度も２億８,０００万円ほどの更正減額がありました。平成１８年度、１９年度はまだ年度途中ですけれども、生活保護の相談者数、それから申請者数、申請後の保護になった件数について、お聞かせ願いたいと思います。","respondent":"志村生活福祉課長","answer":"生活保護費６億円の減額の内容について、ご説明を申し上げます。平成１９年度予算ですけれども、編成に当たりましては、平成１８年秋ごろ、まだまだ生活保護の申請件数の伸びが見込まれた時期です。","voiceIndex":108,"id":"exchange-044"},{"speaker":"菊地委員","kind":"質問","question":"２,０００件、これは相談件数ということですよね、要は。保護の申請そのものが何件ぐらいあるのかということ。保護が申請をされて、それから決定をするわけですから、保護の申請そのものが何件ぐらいあるのかというのを、ちょっとお聞かせ願いたいんです。ちょっと分析まで聞いていると、時間がなくなりますので、ちょっと先に、申請そのものが幾つあるのか、ちょっと先にお聞かせ願いたいと思います。","respondent":"志村生活福祉課長","answer":"ほとんどが２週間以内に保護の決定を行いますけれども、そのうち取り下げたといいますか、後になっていろいろ要件が整わなかったものにつきましては、今年度については１０件です。ですので、ほとんどのケースの場合は、そのまま申請、保護の受給という内容です。","voiceIndex":110,"id":"exchange-045"},{"speaker":"菊地委員","kind":"質問・要望","question":"保護法の第７条に、保護は、要保護者、その扶養義務者、または同居親族の申請に基づいて開始をするというふうにありますから、制度の仕組みとしては、保護請求権がまず先にあって、保護申請書を書いて、それから実際に生活保護に適用できるのかどうかという審査があるんだと思うんです。その辺、ちょっともう少し教えていただきたいと思います。","respondent":"志村生活福祉課長","answer":"私ども、先ほど申し上げましたように、年間でいろいろな相談をやってまいります。その中で、生活相談なんですけれども、いろいろな複雑な内容が多岐にわたってあります。いろいろ社会保障制度の活用ですとか、手当ですとか、年金ですとか、このようなご紹介をしております。","voiceIndex":112,"id":"exchange-046"},{"speaker":"菊地委員","kind":"質問・要望","question":"今は、もっとひどい状況にある。実際に区としてこうしたネットカフェなんかで、アパートさえ借りることができないという状況に陥っている方たちの人数ですとか、あるいは、保護基準以下で暮らしている人数を押さえておられるのかどうか、つかんでいれば、この辺の数を教えていただきたいと思います。大変な数なんですよね。この辺をちょっと押さえているのかどうか、お聞きしたいと思います。","respondent":"志村生活福祉課長","answer":"ですので、私どもでは、そこの対応の中でいろいろ、私どもの今の現在とっている施策のほうの、例えば相談ですとか、あるいは、ホームレスの路上対策等にいろいろな問題が出てくると思いますので、その対応の中で図っていきたいと、このように考えてあります。","voiceIndex":114,"id":"exchange-047"},{"speaker":"菊地委員","kind":"意見","question":"要は、申請主義をとっているからといって、要保護者の発見を自治体が見過ごしてもいいんだということを言っているわけではないんですよ。それから、昨年１０月、国会で福田首相も、こんなことを言っています。本来、区がやるべき仕事というのは、一つには、生活に困窮する人たちにあらゆるお知らせをしていく、見つけ出すということも、区の仕事ではないかと思いますけれども、この辺はお聞かせください。","respondent":"志村生活福祉課長","answer":"このような申請がとれない場合もあります。職権で解消するという窮迫の場合のものもあります。ですので、私どもでは、いろいろな相談を受ける中で、その一つの選択肢だと解釈しておりますので、現在、このような考え方で進めているところです。","voiceIndex":116,"id":"exchange-048"},{"speaker":"菊地委員","kind":"質問","question":"申請を受け付ける、区役所の窓口、それからそれぞれの地域センター、あるいはネットカフェでもいいですよ、こういうところにきちんと申請書を置く、あるいは本会議の質問でもありましたけれども、手引き書をきちんと置く、こういうことを進めなければ、本来行政が果たすべき生活保護法にのっとった役割は果たせないということなんじゃないですか。もう一度、その辺のご答弁をお願いします。","respondent":"志村生活福祉課長","answer":"ご説明する中で、生活保護の説明というのも出てくるんだろうということで考えておりますので、個別の相談の中でＰＲをしていきたいと考えているものです。","voiceIndex":118,"id":"exchange-049"},{"speaker":"大沢委員","kind":"意見","question":"６１ページの退職手当、それから、１６０ページの介護保険を聞かせていただきます。６１ページの退職手当なんですが、９７ページに明細があります。ちなみに、平成１７年度でプラス補正ですが、２億円、平成１８年度では６億５,０００万円余、平成１９年度補正においては７億２,８００万円余の補正がされております。これはどういう理由なのか、お聞かせください。","respondent":"榎本人事課長","answer":"ですから、定年退職者の数が年々増加してきた関係で、当初予算の部分は増えてきていますけれども、補正はそれに見合う、年度中途退職、もしくは定年前の退職者をカウントした年度末での見込みという形で計上しています。","voiceIndex":121,"id":"exchange-050"},{"speaker":"大沢委員","kind":"質問","question":"ただいま、お話の中で、途中退職、それから年度末ですから勧奨退職だと思うんですけれども、途中退職の方は何人いらっしゃるのか、教えてください。","respondent":"榎本人事課長","answer":"今現在、年度途中での退職が５４名という形です。","voiceIndex":123,"id":"exchange-051"},{"speaker":"大沢委員","kind":"質問","question":"５４名といいますと、全庁の職員に占めるパーセントはどのぐらいなのか、計算すればわかるんですが、おおよそどれぐらいになるものか、教えてください。","respondent":"榎本人事課長","answer":"およそ２％になります。","voiceIndex":125,"id":"exchange-052"},{"speaker":"大沢委員","kind":"質問","question":"途中退職をされる中で、特徴といいますか、主立った年代層、そして性別は別にして、途中退職の主立った特徴が見られるようでしたら、お伺いしたいと思います。","respondent":"榎本人事課長","answer":"年度途中退職の中で主立ったものというのは、自己都合退職の場合には、各年齢、準定年、それから５０歳以上、５０歳以下の退職と、大体同じぐらいの数字が出ておりますので、特に主立った特徴はございません。","voiceIndex":127,"id":"exchange-053"},{"speaker":"大沢委員","kind":"質問","question":"事務系が多いということですけれども、そこのところが伺いたかったんですが、何ゆえ事務系が多いのか。それが、何か事業部が偏っているところがあるのか、それともまんべんなく事務系がおやめになっているか、それをちょっとお伺いしたいと思います。","respondent":"榎本人事課長","answer":"特にどこでという所属で偏っているという形ではなく、事務系はもともと人数が２,７００人をベースと考えますと、１,０００人近くが事務系の職種ですので、その中での人数が多くなってきているのかなです。","voiceIndex":129,"id":"exchange-054"},{"speaker":"大沢委員","kind":"質問・要望","question":"まさに私、そこのところが伺いたかったところでありまして、若い２０歳代から３０歳代の若い方たちがやめていかれる、途中退職をされる。ご自身の職務に対してのまた新たな挑戦ということも、それもよかろうかと思います。そこについてのお考えがありましたら、聞かせていただきたいと思います。","respondent":"榎本人事課長","answer":"若い世代が、若干多くなってきたかなという傾向はありますけれども、実際には、ここ数年、新規採用を増やしておりますので、実際の統計上の数字で見ますと、２０歳代の職員が、前年比でいきますと１.９％増えているとかいう形で、３０歳代が若干落ちていますけれども。","voiceIndex":131,"id":"exchange-055"},{"speaker":"大沢委員","kind":"質問・要望","question":"今後の教育に期待したいと思いますので、よろしくお願いしたいと思います。きちっとやっているのはわかっておりますので、すみませんが、よろしくお願いしたいと思います。すみません、手短に。私、前回のときに一般質問で、老老介護の問題を質問させていただきました。ゆえに要らないとはおっしゃっていないわけでありまして、少ないと考えていらっしゃるところのお考えをお聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"したがいまして、数区で独自のサービスを創設しているところもありますけれども、今のところは、区としては適切に対応してきていると考えているところです。","voiceIndex":133,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"私は、６１ページの議会費、同じく６１ページ、近隣セキュリティシステム、そして６９ページのすこやか子ども医療助成について伺います。そういう議論があるということを踏まえて、議会費の中で、今までに予算として計上されていなくて、プラスの補正ということで何か事例があったか、どうかということを、まずは一つお伺いをしたいと思います。","respondent":"市岡区議会事務局長","answer":"１０年ぐらいさかのぼりますと、平成のはじめのころ、職員を含めて給与改定がプラスの時代でしたので、報酬改定が４月１日ではなくて、年度の途中で行われたというときに、補正があった年が若干あるかなと、それ以外はないと思います。","voiceIndex":136,"id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"人件費とか、報酬に関してのプラス補正であったということなんですけれども、補正というか、こういう予算の立て方について、ちょっと考え方をお伺いしたいと思うんです。予算計上がなかったとしても、緊急かつ、区民にとって重要で、必要な調査活動ということを議会が決定した場合に、区として補正の支出が可能であるかどうかということを、考え方としてお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"補正予算ということで、当初、計上されなかったもので、その後のいろいろな事情の変化、状況の変化というのは、当然あるわけでありまして、それを踏まえて、補正予算として計上されるということがまず第一義でございまして、そういう形での計上がなされれば、当然。","voiceIndex":138,"id":"exchange-058"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。次は、子どもすこやか医療費助成についてなんですけれども、先ほど、少し同じような議論がありましたけれども、重なるところもあるかもしれませんが、お答えをいただきたいと思います。１点は、今回の医療費、２,９００万円ほどの補正がありますけれども、これがどのように分析をされているのかということを、まず一つ、お伺いしたいと思います。","respondent":"諸岡児童課長","answer":"加えて、特効薬ですタミフル等の使用も、一部、子どもには制限されているということもあって、症状が長引いて、診療回数等の増加ということも見込まれたということがございました。","voiceIndex":140,"id":"exchange-059"},{"speaker":"井上委員","kind":"質問","question":"今のお話ですと、積算は十分であったけれども、インフルエンザとか、そういう流行、疾病の関係で増えると。これはもう既に支出をされたということではなく、そういうことを勘案して、補正を組まれたのか。それとももうそれだけの支出があって組まれたということなんですか。ちょっとその辺がよくわからなかったんです。","respondent":"諸岡児童課長","answer":"これまでの執行につきましては、ほぼ予算どおりです。今後、いろいろそういった懸念があるということで、予防的に補正をお願いしたです。","voiceIndex":142,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"わかりました。それにあわせて、現実にも、五反田地域では保育園の入所が大変厳しいエリアになっている。東品川のほうでも、児童数がいっぱいになっているという現実があるわけです。医療費のことに関してお聞きしているので、今後、５年間ぐらい先、その世代の人口動向をどのように評価、推測しているのかお伺いしたい。","respondent":"諸岡児童課長","answer":"今後の人口推計をどう考えるかというのは、これは難しいことでございまして、そのときどきで、やはり予算編成のときに判断をしていかなきゃならないと考えております。","voiceIndex":144,"id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"そこで、平成２０年度の予算は、今回の最終の補正額に比べても、２億７,９００万円という増額になっていて、これから人口はその都度評価をしていくということだったんですけれども、そうなったときに、子どもの数に合わせて予算の増額をしていかなければいけないということが前提にあるわけですが、その中でも、医療費抑制の取り組みというのは、ある程度考えていかなければいけないと思いますが。","respondent":"諸岡児童課長","answer":"経済的に負担がないということで、こういうことに率先してやっていただくということで、疾病の慢性化でありますとか、またそれを長引かせて大人になるまで引きずっていってしまうということのないように、早期治療ということを目的として、最終的には。","voiceIndex":146,"id":"exchange-062"},{"speaker":"井上委員","kind":"質問","question":"私が医療費抑制の取り組みについてというところでお伺いしたのは、今、医療費の無料化によって、品川区だけということではなくて、そういった地域で、コンビニ受診が大変増えている。無料だからということではなく、その分が税金として支出をされているということを、ぜひ工夫をして知らせていくことが必要だと思いますけれども、その点については、いかがでしょうか。","respondent":"諸岡児童課長","answer":"したがいまして、私どもは、そういったことに対する啓発にいたしましても、医療費助成について、医療費の無料化ということではなくて、医療費の助成、つまり。","voiceIndex":148,"id":"exchange-063"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺のところは、お願いをしたいと思います。次は、近隣セキュリティシステムです。それからもう一つは、機種トラブルとか、オペレーター経費を含む運用経費、まもるっちの通信費用など、近隣セキュリティ事業全体にかかわる予算が、今後も含めて、毎年幾らぐらいと必要と見込んでいるのかということをお伺いしたいと思います。","respondent":"中山地域活動課長","answer":"近隣セキュリティのその他の予算経費ですが、今後の経費ですけれども、これは平成２０年度予算にもかかわる部分でもありますけれども、基本的な運営経費としましては、今回、補正後、約１億８,０００万円ぐらいになるわけですけれども、通常のランニングということを考えますと。","voiceIndex":150,"id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"その費用対効果というものは、今後、考えていかなければいけない問題だと思いながら、品川区が近隣セキュリティシステムを導入するときに、機械に頼るのではなく、地域の方々の見守りによるコミュニティこそが本来の目的であるということを、私が以前総括質問で質問をしたときに、そのような答弁をいただいておりますけれども、その姿勢は今でも変わらないのでしょうか。","respondent":"中山地域活動課長","answer":"いわゆる協力者は、今、ほぼ１万３,０００人ぐらいいらっしゃいますけれども、このような方の見守り。","voiceIndex":152,"id":"exchange-065"},{"speaker":"井上委員","kind":"質問","question":"学校でも８３運動を展開をしている、そして、我がまちパトロール隊も、多くの方々の協力を得ている。実際には、子どもたちに配られて３年目ですけれども、そろそろ費用対効果を、本来、考えていく時期にきているのではないかなと思います。皆さんから地域の皆さんで見守り合うまちづくりこそ、目指すほうがいいなと思います。そのことについて、品川区のご意見をお伺いしたいと思います。","respondent":"中山地域活動課長","answer":"こういうことによって、固定的な経費を下げられる可能性というのはあるかと思いますけれども、これはあくまでも事業上の努力でありまして、基本的なスタンス、子どもの命に関してきちんと事業費をかけていく考えというのは変わるものではございません。","voiceIndex":154,"id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"私のほうから、８６ページの学校給食費にかかわるところで、まず一つ確認させていただきたい。その納入された金額から、業者、町場の八百屋とか、豆腐屋に支払われていると認識しておるんですが、例えば、学校給食の中で、未払いの問題ですとか、平成１９年度におきましては、特に食材料の高騰の問題があった中で、例えばこの冊子の中に補正されているのか、どうなのかということを、まず確認したい１点です。","respondent":"古里学務課長","answer":"学校給食の食材費に係るご質問ですが、基本的に、学校給食の食材費については年度会計でございまして、その年度の中で赤字が出ないように運営するということになってございまして、公費に係わる補正経費の中には、そうしたものはございませんし、学校の中でも。","voiceIndex":158,"id":"exchange-067"},{"speaker":"渡部委員","kind":"確認","question":"であれば、もともと未納があるだろうということを頭に入れて集金をされているのか。僕が一つ気になったのは、例えば、学校等での経費、ここの冊子を見ていてちょっとわからなかったものですから、ほかの学校等の経費の中から、そこに若干でも補てんがあるのかと思いましたので、その辺を確認させていただいたんですが、お願いします。","respondent":"古里学務課長","answer":"学校給食は、ひとえに学校長の権限で行っているものでございまして、学校長と、学校に配置されている栄養職員が、徴収されている学校給食費、いわゆる食材費の中で献立を立て、執行をしているですので、公的な部分での補てんということはしておりません。","voiceIndex":160,"id":"exchange-068"},{"speaker":"渡部委員","kind":"質問","question":"その食材費の部分で、毎年、学校給食費というのが決まりまして、各家庭が食材料費を負担するわけですが、また平成２０年度のことになってしまうかもしれませんが、平成１９年度と比べて、各学年給食費というのは違いますから、幾らというのはいいんですが、食材料の高騰等を踏まえて、平成２０年度の給食費は、若干の値上がりというと言葉が悪いんですが。","respondent":"古里学務課長","answer":"食材の高騰につきましては、現在、注意深く調査をしておるところでございまして、来年度早々ということで、今、作業を進めているものではございませんが、注意深く見守っているです。","voiceIndex":162,"id":"exchange-069"},{"speaker":"渡部委員","kind":"質問・要望","question":"その辺で、豆腐屋はちょっとおくれていたと思うんですけれども。栄養士も、町場の商店も、お互いがきつい中でぎりぎりやってきているのかなと思っているんですが、その辺は、７月分は、例えば８月中頃まえに支払われるという形で、年度当初の支払関係をうまくやる方法って何かないんでしょうか、教えてください。","respondent":"古里学務課長","answer":"給食費は、ご案内のとおり私費会計でございまして、新入生が入って後、振込口座を指定していただくという手続が、急ぎ行いましても、銀行とのやりとりを含めて１カ月余はかかってしまいます。","voiceIndex":164,"id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"６１ページの私立学校関係費更正減額という部分で、マイナス５,９３３万８,０００円という金額が出ています。そう見ますと、５,９００万円という減額は大きいと思ったんですが、これは純粋に子どもが少なかったのか、何でこの６,０００万円近い金額のマイナスが出ているのか、教えていただけますでしょうか。","respondent":"高橋幼保一元担当課長","answer":"お尋ねの私立学校関係費更正減額のことについてです。当初予定していましたものよりも５,９００万円、今回は、補助金を受ける保護者が高額になったというところでの減額。","voiceIndex":166,"id":"exchange-071"},{"speaker":"渡部委員","kind":"質問・要望","question":"最後に、同じく６１ページの近隣セキュリティシステム運営経費に関連する部分かと思うんですが、近隣セキュリティシステムのまもるっちそのもの自体に対して、ちょっと思ったことがあります。例えば、先ほど、ほかの委員の質問の答えで、１年生のときに渡して６年生まで使うという話だったんですが、やはり機械ものですから、６年持つと、途中で故障とかがあると思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-072"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、２点、８３ページの都市開発費のうちの密集住宅市街地整備促進事業追加分の中の用地取得費、３,６６０万円についてと、７７ページの中小企業対策費の中の、チャレンジマート事業更正減額１,６４０万円、この２点についてお伺いをいたします。今回、用地取得費が３,６６０万円、補正で組まれておりますが、その内容について簡単に教えていただきたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"密集住宅の用地費ですが、実は、９月の補正の段階で、１億７,５１３万３,０００円を計上させていただきましたわけですが、この分については、既に執行済みで、当初、６,７４０万円の用地取得費を見込んでおりましたが、その後に、都市開発公社のほうで先行取得して。","voiceIndex":170,"id":"exchange-073"},{"speaker":"武内委員","kind":"質問・要望","question":"そうしますと、今、土地開発公社云々がありましたけれども、いずれにしても、当初の予算よりは大幅に用地取得をしてきたということで受けとめさせていただきたいと思います。その辺、今年度も含めて、その辺の認識というか、どのような形で頑張ってきたかということについて、思いというか、お知らせいただきたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"ただ、そうは言っても、１０番目以内ではないんですが、やはり危険度の高い地域がやはりありますので、引き続き密集事業等を積極的に進めていきたいと考えております。","voiceIndex":172,"id":"exchange-074"},{"speaker":"武内委員","kind":"質問・要望","question":"そういった面では、これが一概にどこまで実態をあらわしているか、なかなかわからない部分もあるんですけれども、今回、発表された危険度調査から見ますと、品川区では、今、４地域で取り組んでいただいていますけれども、私が見た限りでは、非常に頑張っていただいているなと、一つは思ったこと。その辺の見通しを、何かありましたら、お聞かせいただきたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"明確にお答えできないで申しわけないんですが、確かに、旗の台、中延地区につきましては延伸がございまして、延伸の考え方というのは、ほかの地区との全体のバランスというものもありますし、あるいは、その地区の改善状況、国のほうで事業再評価の対象に入れるかどうか。","voiceIndex":174,"id":"exchange-075"},{"speaker":"武内委員","kind":"質問・要望","question":"例えば東中延と豊町の地域が、この事業が始まっております。例えば、今、私が住んでいる近くでも幾つかあいてきて更地の状態ですけれども、今後、こうしたところは、公園ですとか、また防災広場としたものに、基本的にはなっていくのかなと思うんですけれども、この辺のところは、どのようになっていくのか、その辺の予定がありましたら、お知らせいただきたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"今後、取得するものについてどうするかというのは、必ずしもそうではないんですが、基本的には、空地を設けて延焼の遮断をするという発想が大事かなと考えています。","voiceIndex":176,"id":"exchange-076"},{"speaker":"武内委員","kind":"質問・要望","question":"自分のところの近所で、ちょっとキャッチボールしたりというスペースがほとんどないような状況の中で、もちろん地域の方のご意見を優先しなきゃいけないんですが、それを踏まえた上で、そうしたことに使っていこうかというお考えはあるかどうか、お聞きをしたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"個別の具体的な子どもたちのスポーツだとか、その辺になると、一概に言えないんですけれども、その辺も、全体の中でどういうふうに考えていくのか、地域の方とお話し合いを進めて、その中で、どういうふうにつくるか決めていきたいと考えています。","voiceIndex":178,"id":"exchange-077"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひ、ひとつそれも参考にしていただいて、よろしくお願いしたいと思います。次のチャレンジマートのほうの更正減額で、一般質問でも取り上げたので、空き店舗がなかなか活用できないという状況は、ご答弁でも伺ったので、いいんですけれども、今回のここに出ている補正で、１,６４０万円だったか、この分が減額になってしまった理由について、教えていただきたいと思います。","respondent":"金子産業振興課長","answer":"一つは、地元でも空き店舗をやろうということで、取り組みを進めている最中に、例えば、事業自体を最終的に実施する段階に至らなかった、あるいは、空き店舗として予定していたところが、地権者の関係、あるいは、貸し主の関係でほかのところに貸してしまったというようなことで。","voiceIndex":180,"id":"exchange-078"},{"speaker":"武内委員","kind":"質問","question":"前段のところというか、伺っているのは、活用したいんだけれども、いわゆる持ち主のほうが、貸すというよりは売ってしまいたいというような意向もあるやに聞いておりまして、どうしても、そういう中では、ワンルームマンションとか、こうしたものに変わっていくような傾向がある。そうしたことについて、見解をお願いいたします。","respondent":"金子産業振興課長","answer":"本会議でもご答弁申し上げましたとおりなんですけれども、商店街の中の拠点となる店舗の購入助成については、営利活動のための不動産取得であるというところから難しいと考えておるわけです。","voiceIndex":182,"id":"exchange-079"},{"speaker":"阿部委員","kind":"質問","question":"先ほど、午前中にも、予算編成面でのチェック体制について、今後の改善ということはご答弁がありましたけれども、契約の相手方の財務状況が芳しくないというような情報を持っているとき、どうかなというような感じになっているときに、相手側から相談を受ける前から、いち早く何か行動が起こせるようなリスク管理のあり方というのもあっていいのではないかと思うんですけれども、この点は。","respondent":"福田企画部長","answer":"これまでもご答弁していますが、危機管理をもう少し幅広くとらえる、そういう必要があるだろうと考えています。","voiceIndex":185,"id":"exchange-080"},{"speaker":"阿部委員","kind":"質問","question":"こういったことを、今後も起こってくる可能性はありますので、ぜひ、早急にご検討をお願いいたします。この機会にでも、まもるっちの本来の主要な機能であります通報機能の安定性を向上させるための方策をとっていくんだというようなお考えはありますでしょうか。","respondent":"金子産業振興課長","answer":"第３世代対応のシステムにしていけば、委員ご指摘の点については、かなり改善されるという予測を持っております。そういう意味で、来年度から、そういう開発をするという予定を立てまして、昨年度、簡易なプロポーザルを実施したところです。","voiceIndex":187,"id":"exchange-081"},{"speaker":"阿部委員","kind":"質問","question":"通報機能ではなく、通話の機能のほうなんですけれども、これはオプションで、先ほどの質問の中でも、１万２,０００件中３,０００件程度契約があるということだったんですけれども、通話料金が、今の携帯電話に比べてちょっと高いんじゃないかというような声を聞いておりますが、現在、どのぐらいの料金になっておりますでしょうか、ちょっと教えてください。","respondent":"中山地域活動課長","answer":"これは事業者と時間によって違うんですけれども、一分当たり４０円から６０円の間です。","voiceIndex":189,"id":"exchange-082"},{"speaker":"阿部委員","kind":"質問","question":"特に相手方はソフトバンクですよね。今は、ソフトバンクでは、いろいろな条件はありますが、家族間の割引については無料というようなこともやっておりまして、それがそのまま使えるかどうかは別として、今後の通話料金の値下げというようなことを検討していく可能性があるのか、どうか、教えてください。","respondent":"中山地域活動課長","answer":"いわゆる有料オプションサービスは、利用者と事業者の相対の契約です。３月１日付で事業譲渡が相成った直後ですけれども、今、ご指摘あったようなご意見について、今後、いろいろな事業者との協定、交渉の中で、そういう声について、区からも伝えていきたいと思います。","voiceIndex":191,"id":"exchange-083"},{"speaker":"阿部委員","kind":"質問・要望","question":"歳入歳出全般という言い方で、ちょっと漠然としていたんですけれども、要は、収入と基金の考え方について教えていただきたいと思います。増収分で基金に４７億円も行っているわけですね。想定外の収入は、基本的に基金に回すという考え方で処理をされたということなんでしょうか、ちょっとその辺の考え方を教えてください。","respondent":"日下部企画財政課長","answer":"最大限、それがどのぐらい入ってくるか見込むわけですけれども、例えば、今回も、区民税を中心にしまして、前年度に課税されるわけでありますけれども、かなり所得というよりも、どちらかというと、納税義務者が当初見込みよりもかなり増えた、２％ぐらい増えております。","voiceIndex":193,"id":"exchange-084"},{"speaker":"阿部委員","kind":"意見","question":"基金をこれからも積み立てていく必要性を否定するつもりはありませんけれども、やっぱりどのぐらいのペースで、どのぐらいの額を積み立てていくんだという、ある程度の目標みたいなものがあるのか、どうか。そして、例えば今回のように、図らずして増えた場合には、例えば、来年度の予算の中での基金の積立額にどう影響していくのか。","respondent":"日下部企画財政課長","answer":"これでいくと、２３区の場合は、ちょっとほかの自治体と一概に比較できないところはありますが、今現在でいくと８５０億円ぐらいの規模にもなりますし、例えば、それぐらいが一つの目安にもなってくるかと、こういうふうに考えております。","voiceIndex":195,"id":"exchange-085"},{"speaker":"阿部委員","kind":"質問","question":"この平成１９年度の間に、利息が急に上がったわけではないと思いますし、多少、基金だとか途中で増えたとしても、利子が倍以上になるような預け方があるのであれば、私も入れてみたいものだと思うんですけれども、大体、こういうものっていうのは、最後の微調整はともかく、年度当初に、ある程度読めるものではないんでしょうか。何でこういうことになるのか、ちょっと教えてください。","respondent":"西島会計管理者","answer":"私どもで、今年購入しましたのは、ほとんどが１.０％の利子で購入いたしました。現在、いわゆる５年国債が０.９幾つですので、そういう意味では、今年度の国債購入の中で一番高いときに運良く購入できたということで、こういう数字が出てきたものです。","voiceIndex":197,"id":"exchange-086"},{"speaker":"山内委員","kind":"質問・要望","question":"よろしくお願いします。私のほうから、８９ページの図書館経費更正減額と、戻りまして、５８ページの諸収入の雑入の都市基盤整備収入について、お伺いをさせていただきたいと思います。その辺はともかくといたしまして、まず、図書館の当初予算の立て方というものを、まずちょっと説明していただきたいと思います。","respondent":"工藤品川図書館長","answer":"図書館の部分の人件費の部分だと思います。当初予算の立て方としましては、前年度の１０月１日の職員の現給をもとに立てたものです。","voiceIndex":201,"id":"exchange-087"},{"speaker":"山内委員","kind":"質問","question":"専門の知識を持った司書の雇用状況といいますか、雇用状態というんでしょうか、その司書に関するポイントと、それからあと１点、団体配本を小学校の図書館に行っているということを伺ったんですけれども、その辺のサービス、今後どう考えているのかということを、ちょっと教えてください。","respondent":"工藤品川図書館長","answer":"私ども、平成１７年４月から、全館窓口業務委託を導入したわけですけれども、やはりその際に、特に私ども方針として考えておりましたのは、同じ図書館サービスをやっていく者として、協働の視点でやっていくです。","voiceIndex":203,"id":"exchange-088"},{"speaker":"山内委員","kind":"確認","question":"次にいきます。都市基盤整備の整備費の収入についてなんですけれども、ちょっと確認をしたいんですが、都市基盤整備費というのは、何か品川区内で、いわゆる企業とか、開発組合が何か地域で整備をするといったときに、準備支度金みたいなものを、品川区のほうへ支払っていただくという、そのようなものですか。","respondent":"青木都市開発課長","answer":"ここに記載されております都市基盤整備収入について、ご説明いたします。一般的に、開発指導などで条例化をして、その開発事業者から負担金を徴収するというのは、いろいろな地方公共団体でやっておるんですけれども、品川区においては、そういった条例や要綱等はございません。","voiceIndex":205,"id":"exchange-089"},{"speaker":"山内委員","kind":"質問","question":"一定のご負担という金額なんですが、決め方というのはどういう形でやるんですか。","respondent":"青木都市開発課長","answer":"基本的には、補助金などを導入した整備事業ですので、それに見合う受益者の負担という考え方で、それは話し合いで決まっておりますので、どの地区でも同じという考え方はないんですけれども、それぞれ開発事業者と協議をしていく中で。","voiceIndex":207,"id":"exchange-090"},{"speaker":"山内委員","kind":"質問","question":"負担額の割合というんですか、その辺は非常に何かなあなあで決められちゃっているのかなと、そういうことはないんでしょうか。","respondent":"青木都市開発課長","answer":"あまり手の内を示してしまうと、話をしにくいんですが、逆に事業者のほうで、どのぐらいの受益だと思うか、どのぐらい支払えるかというところも話し合いをしていく中で探った上での協定締結ということになっておりますので、今。","voiceIndex":209,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"５３ページの都補助金のところでのすまいるスクール運営費補助。時間がありましたら、４７ページの原小学校跡地利用についてご質問いたします。２２区分が３８区分ということで。歳出のところでは、これらの支出金があることによって、一般財源を更正減額しているということがありますけれども、これを、区はどういうふうな考え方を持って見ているのかを聞きたいと思います。","respondent":"日下部企画財政課長","answer":"歳入のほうにつきまして、項目がかなり増えているというご指摘ですけれども、これは、例えば、先ほどご説明を申し上げました、５０ページ、都補助金で申し上げますと、福祉包括の補助金が分野別でかなり切り分けがされた。それだけ１項目が四つに増えたわけです。","voiceIndex":212,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"要するに、品川区の事業、行政サービスをしていく中で、通常は一般財源を使った形でしているわけですよね。それが、国とか都から支出されて、それを補正という形で計上しているということになります。ということは、来年度の予算、毎年、来年度の予算書をつくるときに、国とか都の補助という考え方ですが、それをどういうふうな考え方を持って予算を立てているのかということですが、いかがですか。","respondent":"日下部企画財政課長","answer":"そういうことで、それぞれの所管が日々アンテナをしっかり立てて、国や都の動向もしっかりと見極めて、最大限、特定財源の確保に努めているです。","voiceIndex":214,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"有効活用という意味では、当然それをお願いしたいところでありますが、有効活用するというのと、国、都から補助金が出るからやろうというような考え方でやっているのか。その見通し、見立てとかというところは考えながらやっているのか。どういう考え方で予算書をつくって、補正という形に成り立っているのかというところは、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"有効活用を図るというのは、今、ご質問にあったような、そういう二つの側面があると思います。一つは、やはり、品川区というのはいろいろな新しい取り組みを積極的にやっていこうと、区長の方針で進めているわけです。","voiceIndex":216,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問・要望","question":"有効活用というところでは、やはり品川区独自の政策というものがありますので、それに則して国とか都の補助金等々を使っていただくということを心がけていただきたいと考えています。それを、品川区で積み上げてやってきていることはきっちりと守っていきながら、事業展開をしていただきたいということで、これは要望として言わせていただきたいと思います。","respondent":"榎本人事課長","answer":"この補正の職員給与費の考え方なんですけれども、平成１９年度当初予算に載せるときの人数は、平成１８年１０月１日現在の職員の配置数という形をもとにして、平成１９年度予算を組んでおります。","voiceIndex":218,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"それからもう一つは、例えば、学校給食費のところの職員給与費は、民間委託とわかっているわけですから、２億円の減額の補正というのはちょっと大きすぎるのではないかなと思うんです。この２億円あるんであれば、ほかのところに事業展開できるんじゃないかと思うわけですけれども、これはただ単にずれですよと、許容範囲の中にあるということなのか。その考え方は、いかがでしょうか。","respondent":"榎本人事課長","answer":"実際に、その年度、何校で調理代行を実施できるかというのは、やはり年末から年明けにかけての契約関係の中で決まってきますので、その配置の部分で、平成１８年１０月１日の段階では、そこまで想定をして出すというのは難しいということで。","voiceIndex":220,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"というのが一つ。その中で、縮減された財源をどういうふうに使っていくかという形になると思うんです。その場合に、これぐらいの差が、ほかのところで計上されているということはわからないではないんですが、それにしても、この金額はこれからどんどん増えていくと思うんですけれども、毎年、こういう補正のところで出てくる金額という認識でよろしいんでしょうか。","respondent":"榎本人事課長、市川庶務課長","answer":"女性の場合は、区の職員の場合１００％近い取得状況の中で、きちんとした取得しやすい環境をつくっていくという意味で、正規職員、それから任期付の正規職員等を基本に補充をしています。ただし、先ほど、人事課長が申し上げましたが、同じページの学校管理費のほうの職員給与費追加分というほうは、約１億円ほど追加で計上しております。","voiceIndex":222,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"職員が何らかの理由で休業に入られるという場合には、その代替をきっちりとっていただきたいということ。そうすると、今回、放課後子ども教室という形で補助されると、多いことに越したことはありませんけれども、二重取りじゃないですが、いろいろたくさんお金が出ていいなと思いますが、これはどういう考え方をもって、今後進めようとされているのかお聞きしたいと思います。","respondent":"市川庶務課長","answer":"今回、補正の歳入で計上させていただいていますすまいるスクールの運営費補助、これは、放課後子どもプランの実施に伴いまして、系列で申し上げますと、文部科学省の系列に属する事業の助成制度です。学童保育クラブとは違う趣旨でのものです。","voiceIndex":225,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"そうすると、要は一つの事業で、２カ所の補助対象になるという理解なんでしょうか。その考え方はどうでしょうか。","respondent":"日下部企画財政課長","answer":"今回、出てまいりましたのは、あくまでも具体的に事業を特定した補助金ということでありますので、ちょっと性格が異なりますので、別に二重で入ってくるとか、そういう類のものではないと受けとめております。","voiceIndex":227,"id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"二重というか、いただけるものだったらたくさんいただきましょうということは変わらないんですけれども、そうなると、すまいるスクールという考え方はどうなっていくのかなというところが、ちょっと気になる。その考え方、将来性についてお聞きしたいと思います。","respondent":"市川庶務課長","answer":"今回、計上させていただいた助成制度も、当初、私どもは使えないということで説明を受けてございました。","voiceIndex":229,"id":"exchange-100"},{"speaker":"西本委員","kind":"意見","question":"すまいるスクールの役割はいろいろと出てきていると思います。当初、始めたころと今とでは、親たちの考え方も変わってきている、子どもたちの考え方も変わってきているというところにおいては、今後、どういう方向に行ったらいいのかということも踏まえて、いろいろ検討をして、事業拡大をお願いしたいと思います。時間がなくなりましたので、これで終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-101"},{"speaker":"高橋委員","kind":"質問","question":"今、お話のあった、８５ページのすまいるスクールについてと、あと教育全般のことを伺いたいと思います。すまいるスクールでは、まず、どのような身分の方が働いているのかということを、ちょっとお聞きしたいんですが、お願いします。","respondent":"市川庶務課長","answer":"全小学校にすまいるスクールを開設しているわけですけれども、各校に１名の児童福祉の専門職、正規職員を配置しています。","voiceIndex":233,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、区の正規職員と、区のほうで採用した非常勤職員と、あとは委託先の正規の方と、委託先が採用した非常勤の方という形で指導されていると伺いました。品川区のほうで、ホームページなどで募集をしたりすると思うんですが、指導員の待遇、収入といいますか、それはどのような形になっているんでしょうか。","respondent":"市川庶務課長","answer":"現在、区のほうで採用しております非常勤につきましては、１日５時間、週５日で、月額約１６万円相当というような処遇で採用しております。","voiceIndex":235,"id":"exchange-103"},{"speaker":"高橋委員","kind":"質問","question":"委託のほうなんですが、運営委託費ということで、これも人数によって違うのか、どのようにして委託先と契約しているかあれですが、１校当たり幾らぐらいで契約をしているんでしょうか。","respondent":"市川庶務課長","answer":"現状では、規模の違いよって、多少の前後はありますけれども、おおよそ、１,２００万円、１,３００万円、そのあたりです。","voiceIndex":237,"id":"exchange-104"},{"speaker":"高橋委員","kind":"質問・要望","question":"平成１９年度と２０年度の予算を、ちょっと見比べてみたら、指導員の報酬が、平成１９年度は２億４,７００万円、平成２０年度は、半分で１億１,０００万円になっています。運営委託費のほうは逆に、平成１９年度は４億２,０００万円、それが平成２０年度は６億円ということなんですが、このあたりのご説明をいただきたいんです。","respondent":"市川庶務課長","answer":"残るのは教員免許を有している非常勤の指導員が残るです。もう１点、委託費の関係につきましては、平成１９年度におきましては、４０校中３１校、業務の一部委託を行ってございました。これが、平成２０年度につきましては、全校で業務委託、この違いです。","voiceIndex":239,"id":"exchange-105"},{"speaker":"高橋委員","kind":"質問・要望","question":"今、いろいろな方が、いろいろな立場でお仕事をされているということですが、これは要望なんですが、委託先の、特に非常勤で委託先から派遣されてくる方たちの研修を、現場のほうでかなりやらなければいけないという部分があるそうなので、これは委託先を決める際のいろいろな要件になると思うんですが、委託先の研修体制を、区のほうできちっと把握していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-106"},{"speaker":"高橋委員","kind":"意見","question":"すみません。では、６９ページの私立保育園の大規模補修経費の補助ですね。こちらは、今年、幾つかの事業をやられたと思うんですが、幾つの保育園で補修が行われたのかということ。それを踏まえて、これは平成２０年度には、またこのような形で補修が行われていくのか、お尋ねいたします。","respondent":"小林保育課長","answer":"これは、計画的にやっていくというものではございませんで、それぞれ私立保育園の施設状況に応じまして、ご希望のありましたものを、区として可能な限り実現する方向で、東京都等の補助金の折衝をしていくという形で決めております。","voiceIndex":243,"id":"exchange-107"},{"speaker":"本多委員","kind":"質問・要望","question":"２点、質問します。１点目は、１２ページの債務負担行為、荏原西地区小中一貫校について。２点目は、８９ページの戸越体育館大規模改修費についてです。以前、夏場ですとか、残暑厳しい夏場前後の利用で、風通しが非常に不足をしているので、その改善というような課題もあったんですが、今回、その辺が改善できたのか、教えていただきたいと思います。","respondent":"市川庶務課長、富田生涯学習課長","answer":"したがいまして、解体工事を先行させ、これにおおよそ３カ月見込んでおりますが、この後に速やかに本体工事に着手をしたいという趣旨で、計上させていただきました。戸越体育館の改修工事についてのお尋ねです。築２０年を経過いたしまして、雨漏りですとか、給排水等、水回り等の不具合が出ているということで、改修工事を行っているものです。","voiceIndex":247,"id":"exchange-108"},{"speaker":"本多委員","kind":"質問・要望","question":"今回、２４カ月ということを有効に考えた場合、当然、その議案についてはしっかりと吟味をして、我々議会が賛否の態度表明があるわけですけれども、第２回定例会というのが、若干、２４カ月の工期が品質管理の上から、もうちょっとあり方というものが何とかならないのかなと、以前、一般質問でも取り上げさせていただいたんですが、執行していく側としての考え方を教えていただきたい。","respondent":"市川庶務課長、富田生涯学習課長","answer":"１点目のご質問ですが、まず、校舎改築事業の場合には、国庫補助事業との関係で、２カ年度の工事の範囲内で収めたいという一つの、私どもの考え方の前提があります。体育館の改修についてですが、体育館を利用します場合に、スポーツ競技を行うということから、窓を開けて風通しをよくして利用されるということは非常に少ないのでありまして、例えば。","voiceIndex":250,"id":"exchange-109"},{"speaker":"本多委員","kind":"質問・要望","question":"開校に合わせて、児童・生徒が校門を入るときに、ひととおり全部区切りがついているというのが望ましいという思いで、手続きにおいて確認をさせていただきました。設計変更があるようなんですけれども、区のこれまでの方針で、目玉といいますか、幼保があったのが、今回、変更するということなんですけれども、その判断基準というんですか、その辺について教えていただきたいんです。","respondent":"市川庶務課長","answer":"その関係で、地下工事をなるべく縮減をして、もともとの計画でございました小中一貫校の体育館施設に限って地下工事を実施することによりまして、工期の面のクリア、それから、大幅な経費の削減ができる、このようなことを踏まえて、最終的に設計変更をしたです。","voiceIndex":253,"id":"exchange-110"},{"speaker":"本多委員","kind":"質問","question":"設計段階での見積もりと、具体的な金額算定が出たときの、今回は、そういういろいろなコストですとか、工期ですとか、そういう理由で判断をしたということで、今の説明でわかりましたが、設計段階での見積もりで、実際の見込みが違ったということについては、どういうふうな考え方なんでしょうか。","respondent":"市川庶務課長","answer":"それに並行いたしまして、いわゆる工事費そのものの上昇というのが、ちょうど背景にございまして、通常の地下工事に要する経費に比較してさらに経費増を見込まざるを得なかったといった二重の要因がございました。","voiceIndex":255,"id":"exchange-111"},{"speaker":"本多委員","kind":"確認","question":"本設計の前の計画の段階での数字の差異がかなり大きいと思って、その辺のことを、ちょっと確認をさせていただきたかったんです。今の質問は補正予算ということで、荏原西地区を質問させていただいているんですが、関連しまして、小中一貫校に限らず、今後、学校改築を進めていく上で、その辺のすべての手続とか、タイムスケジュールについては、同じような考え方でいいんでしょうか。","respondent":"市川庶務課長","answer":"ただ、現実問題、まだかなり２４カ月という壁は高いものと感じておりますけれども、少なくとも全体の流れの中で、この辺の助成制度、補助金制度の運用ということで動きがありますので、今後の事業の際には。","voiceIndex":257,"id":"exchange-112"},{"speaker":"若林委員","kind":"質問","question":"私は、６７ページの認知症高齢者グループホーム施設に関する更正減額。それから、７１ページの品川保育園の移転の整備の減額、もう１点は、７５ページのみどりの基金の積立について、お伺いしたいと思います。６７ページ、７１ページのそれぞれの更正減額について、理由、またこれまでの経緯をお知らせいただければと思います。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"これにつきましては、冒頭、企画財政課長からご説明がありましたように、当初、着工時期が９月の予定であったものが１１月に延伸になったことにより、その出来高の、平成１９年度、２０年度の変更に伴う更正減額です。７１ページの品川保育園移転整備、今、ご説明いただきました一体施設の中の保育園部分で、理由は同様です。","voiceIndex":260,"id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、今の入札の不調につきまして、ここも含めまして、平成１９年度の傾向、契約が何件契約があって、何件不調になったのか。多少詳しい概要をお知らせいただきたいと思います。この数年間の傾向、また、どうして不調になるのかということにつきましても、お話をちょうだいしたいと思います。","respondent":"中島経理課長","answer":"ただいまの不調に関するご質問にお答えいたします。不調と申しますのは、いわゆる最初の入札で落札できなかったというのが不調でございまして、その後、結果的には契約になるというものです。","voiceIndex":263,"id":"exchange-114"},{"speaker":"若林委員","kind":"質問・要望","question":"例えば、予定価格の積算基準について一つ、東京都の財務局の積算基準が、今は年に４回改定となっておりますけれども、これに合わせて、区のほうでも、こういった考え方、いわゆる当初の積算から契約をする際、入札をする際の実勢の価格に合わせた反映をさせていきたいというお考えがあると思うんですけれども、それについて、一言お願いしたいと思います。","respondent":"宍戸施設担当課長","answer":"これまでは、年に１回程度改定していたものを、このところの建設費の高騰ということで、年に４回やっているところですが、それに加えまして、部分的な改定等につきましても、その都度やっているところです。","voiceIndex":265,"id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ、よろしくお願いいたします。特に教育施設、またこういった高齢者の施設、子どもの施設が不調になりますと、２回まで入札が行われて、その後は、たしか随意契約というルートがあると思うんですが、一つだけちょっと確認します。１回目が不調になって、２回目に入札が入ると、この期間というのはどのぐらいあるのかというのを、一つ確認をさせていただきたいと思います。","respondent":"中島経理課長","answer":"今、ご質問の期間の問題ですけれども、制限付一般競争入札と、指名競争入札がございまして、指名競争入札というのは１,０００万円以下の工事案件ですけれども、これについては、予定価格を公表してございませんので、１回そこで不調になりますと。","voiceIndex":267,"id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"そしてその後、予定価格との参考にする、そういう新方式を試しに、今、行っているそうです。今回、６億円の積立金があります。現在は４億円で、これは国債での保有ということになっていると思いますが、今回の補正の６億円というのは現金でしょうか、それとも国債で保有されるのか。その現金と債権として保有するものの使い方の違いというものを教えていただければと思います。","respondent":"日下部企画財政課長、藤田道路公園課長","answer":"ただ、来年度以降の運用につきましては、できるだけ有利な国債の活用も含めて、その辺をどうしていくかというのは、今後、会計管理室を中心にいたしまして、その辺の判断はしてまいりたいと考えています。果実の運用としての検討をしていきたいと考えておるところです。","voiceIndex":269,"id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１６０ページからの介護保険特別会計について、お聞きしたいと思います。特に１６４ページの基金積立金についてお聞きしたいと思います。そして、この基金が、今までも１７億円を超えていたわけですけれども、これは２３区の中でもダントツでトップという基金のため込み額になるわけです。そして、これから、その基金についてどのように使っていくと考えているのか、お聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"ということで、３期は平成１８、１９、２０年度までの事業計画期間になっておりますので、その中で、今後、どういう推移をしていくのか見極めながら、基金については基本的に保険給付として使うのが第一でありますので、今後、第４期の事業計画を策定する中で。","voiceIndex":273,"id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すぐにできることとしては、地域センターですとか、文化センターですとか、区の施設には、せめて置いてほしい。今、置いてありませんので、ぜひこれをしていただきたいということが１点なんです。そこのところで、特に、今回はヘルパーサービスの３億３,０００万円削減されたこの実態に、区としてどういうふうに取り組んでいくかというところで、ぜひお聞きしたいというのが３点目なんです。","respondent":"蓼沼高齢福祉課長","answer":"普及啓発については、区としても十分に努めていきたいと考えておりますので、これについては必要な対策を講じていきたいと考えております。それから、認定率の件ですけれども、２３区におきましても、各区において認定審査の方法が違います。","voiceIndex":275,"id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一度お願いしたいと思います。そこの還元の仕方として、一つは、利用料の減免制度をぜひつくってほしい。そのことを、私たちは前も求めてきましたけれどもと、ぜひ検討いただけないかということが１点です。しかも、１２０万円というのは、ほかの区と比べてもほんとうに低いところですので、ぜひここも、せめて生活保護基準並み、そこまで引き上げるべきだと思うんですけれども、いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"自立支援の関係ですが、先ほど申し上げましたように、適切なケアマネージメントで対応してきていると考えておりますので、独自のサービス創設ということは考えておりません。","voiceIndex":277,"id":"exchange-120"},{"speaker":"松澤委員","kind":"質問・要望","question":"私からは、品川区の一般会計の補正予算について、３点。１１ページの第２表繰越明許費、６款土木費、３項道路新設改良費、商店街電線類地中化事業１億５,７０８万円についてが１点。３点目が、第３表の債務負担行為補正（その２）の排水施設建設（戸越幹線貯留管中流部整備工事その１）についての３点をお聞きしたいと思います。この点について、説明をしていただきたいと思います。","respondent":"松代管理工事課長","answer":"地中化の関係です。支障物件です。今回の地中化をするに当たっては、幅員が７ｍぐらいのところにボックスを入れて電線の架空線を地下に落とすという作業です。当然のことながら、今の道路の中にあるいろいろな企業者物件の管があります。","voiceIndex":280,"id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"わかっていて、いろいろ事前にやっているうち支障が出だした。それはわかりますけれども、ここは平成１８年から２３年まで、戸越銀座の長い通りを工事をするわけですよね。それがまた１年延びるということは、工事期間がまた１年延びるということなんですか。２３年までが平成２４年になるということなんでしょうか。どこで、その工事をするのかということを聞きたいと思います。","respondent":"松代管理工事課長","answer":"工期的には、３カ月ほど延びる。平成１９年度の末、今の時期ですけれども、本来であれば、平成１９年末までに仕上げる工事が、こういった調整の関係で３カ月ほど延びるということで、全体の工期は、今の予定どおりの工期の中で何とか詰めていきたい。","voiceIndex":282,"id":"exchange-122"},{"speaker":"松澤委員","kind":"質問・要望","question":"説明は、よくわかりました。実は、この電線地中化、今、話題になっています道路特定財源の暫定税率が廃止とか、延長になったら、これはできないんじゃないかという話が、商店街であるんです。これについてどうなのかということを、しっかり聞いてもらいたいと言われてまいりましたので、しっかりとお答えしていただきたいと思います。","respondent":"松代管理工事課長","answer":"そのために、道路特定財源を何としても、これまでと同様に導入することで事業を進めたいと考えておりまして、引き続き国のほう等には、その旨伝え、協議をしています。","voiceIndex":284,"id":"exchange-123"},{"speaker":"松澤委員","kind":"質問","question":"この問題は、ほんとうに商店街で話題になっていますので、この点もしっかりと説明をしていきたいと思います。踏切の改良工事、９,８００万円。東急がちょっと待ってくれ、高さを調整したいんだということになると、その待ったがかかったのと、高さを調整するためにまた経費がかかると思うんですけれども、これは東急が負担するということでよろしいんでしょうか、それをお聞きしたいと思います。","respondent":"松代管理工事課長","answer":"そういう中で、なぜ調整等が若干おくれたかですけれども、昨年９月に、９月補正でこの大崎２号踏切を計上させていただきました。その後、正式な調整ということで、鉄道事業者の東急池上線、東急電鉄と、この踏切の改修に当たって詳細な打ち合わせを始めたところです。","voiceIndex":286,"id":"exchange-124"},{"speaker":"松澤委員","kind":"提案","question":"実は、ちょっと意地悪な質問になるかもしれないんですけれども、踏切の改良については、私も何回となく、下神明１号踏切、苗木原踏切の改良ということを提案してきたんですけれども、なぜここが第１号に選ばれたのか。私は、三つの踏切を見たら、一番必要度があるのは、大崎高校のところと下神明１号踏切かなと。頭の中の順番では、戸越銀座のところは３番目ぐらいかなと。なぜここが選ばれたのか。","respondent":"松代管理工事課長","answer":"若干説明します。踏切対策ということで、国の動きが平成１７年３月にありました。","voiceIndex":288,"id":"exchange-125"},{"speaker":"松澤委員","kind":"質問・要望","question":"説明、わかりました。３点目、１２ページの債務負担行為補正、その２の廃止。排水施設建設（戸越幹線貯留管中流部整備工事その１）が廃止になった。当然、７９ページにも、更正減額となっていますけれども、この理由について、お聞かせいただきたいと思います。","respondent":"家壽田下水道河川課長","answer":"今回のこの工事につきましては、東京都からの受託事業です。当初の予定ですと、都との協定ではありますが、平成１９年度からの３カ年で施工する予定でございました。当初は、東京都の単独事業として実施する予定でございました。","voiceIndex":290,"id":"exchange-126"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。ただ、この事業、要するに災害がいつ来るかわからないという中の補助金ですから、まだつかないうちは、早くつけてくださいと要望しているんですけれども、ついたとなったら、１年延期されて、その１年間に洪水があったら、溢水があったらどうしようって、だれでも考えるんですよね。その辺をちょっとお聞きしたいと思います。","respondent":"家壽田下水道河川課長","answer":"つまり浸水の起こる、危ないときには通れるようにするということで考えておりますので、地元の皆様方の心配は最もですので、その辺も、しっかりと対応させていただきたいと考えております。","voiceIndex":292,"id":"exchange-127"},{"speaker":"須貝委員","kind":"確認","question":"私は、８４ページの教育費の中の教育指導費全般について、ちょっとお聞きしたいと思います。これは、教育職員免許法で違反ではないのか、どうかという簡単な質問です。お答えください。そしてまた、代表質問の答弁では、片方の免許しか持っていない教員が、小学生や中学生の両者に、生活指導、学年指導をできるようなことを答弁で言われましたが、確認の意味を含めてお答えください。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":296,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"私は、今、申し上げましたが、教育指導費ということ、やっぱり教育全般についてお聞きしたいので、それにもしこだわるなら、今後、一切この内容以外はできないと解釈されるんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-129"},{"speaker":"須貝委員","kind":"確認","question":"わかりました。じゃあ、ちょっと委員長に確認なんですが、現在、書いてある品川区各会計補正予算、ここに書いてある補正、そしてその金額について載っているもの以外は一切質問しちゃならないということでよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":300,"id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"それならば、ここに教育費、教育総務費の中ていろいろ書いてありますよね。それについてだめだということですか。それだったら、こんなふうに大がかりに書かないで、そこだけ列挙していただければ、それ以外は一切質問できないという解釈を、我々もしますけれども、どうなんですか。","respondent":"鈴木（真）委員長","answer":"今の質問に対してのお答えは、そのとおりです。","voiceIndex":302,"id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"わかりました。では、私の質問は終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-132"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうからは、４２ページ、特別区財政調整交付金、５０ページ、都補助金、それから４２ページの負担金、４４ページの手数料、５８ページ、雑入に記載されている認定こども園の保育料、入園料、預かり保育料等について、お伺いをいたします。２点目は、特別交付金について。当初予算、５億円に補正額５億円を追加され、毎年、補正をしていなかったものを、今回、なぜ補正されたのか、その理由について。","respondent":"日下部企画財政課長","answer":"今までは、大まかな項目で明示をされていただけでありますけれども、これについてやはり、今申し上げました算定の公平性、透明性を明確にするという意味で、やはりきちんした基準、ルールをはっきりとすべきではないかということで、都区間で。","voiceIndex":306,"id":"exchange-133"},{"speaker":"山路委員","kind":"質問・要望","question":"ここで、都区財調協議におきまして、区側が、交付金の割合を５％から２％戻すように主張されているのは、この先の見通しについては、どのように考えていらっしゃるのか、教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"現実的に、じゃあその見通しということでありますけれども、なかなかこの辺は難しいところでありますけれども、今、申し上げました三位一体改革に伴う税収減についての、その辺の措置の期間が４年間というようなことでの取り決めをしている経過もありますので、一つには、やはり。","voiceIndex":308,"id":"exchange-134"},{"speaker":"山路委員","kind":"質問・要望","question":"認定こども園の保育料は負担金、入園料は手数料、預かり保育、延長保育利用料は雑入と分れていますが、ちょっとこの辺が、補正予算書からでは内容がわかりにくいんですが、この理由についてお聞かせいただきたいと思います。","respondent":"高橋幼保一元担当課長","answer":"最後の手数料のことですが、これまで入園料というのが保育園にはございません。入園料については、入園にかかわる事務ということで、これは幼稚園にあわせまして手数料のほうに入れさせていただいて、今回、保育の実施等に関する条例の中で定めさせていただいたところです。","voiceIndex":310,"id":"exchange-135"},{"speaker":"山路委員","kind":"意見","question":"時間がないので、ちょっと先に行きますけれども、都補助金についてですが、福祉施策包括補助金がなくなって、四つの分野に再編成されているということで、午前中、金野委員のほうから主な事業をお聞かせいただいたわけですが、なぜ当初予算に計上されてなくて、最終補正に計上されたのか。今後、総額で比較するとどうなっているのか、この辺について、聞かせてください。","respondent":"日下部企画財政課長","answer":"最終補正への計上でありますけれども、実は、これは一昨年の秋口からいろいろ見直しの動きがございました。ただ、平成１９年度の当初予算を編成する段階では、まだその詳細が明らかでありませんでしたので、当初予算で計上することができなかった。","voiceIndex":312,"id":"exchange-136"},{"speaker":"土井委員","kind":"質問・要望","question":"同様に５２ページ、５３ページにあります都補助金絡み、そしてその使い道としての都市計画道路とか、福祉のさまざまなものとか、公園のあれだとかというところに関連をして、そこに大きな減額がありますものですから、そこら辺の内容等について、ちょっと聞かせていただきたいというのが１点。とりあえず、それらについてお伺いをしたいと思います。それでよろしいんだと思うんです。","respondent":"浜脇街路事業担当課長、日下部企画財政課長","answer":"あるいは、若干工事の中で、変更をしたためによる残、そういったことが、ここに書いてある更正減額になっています。ご質問にお答えしたいと思います。例えば、予算書の６３ページをお開きいただきまして、歳出で一番最初に出てくる財源更正ということで、ちょっと今、開いてみますと、例えば７目の防災対策費です。","voiceIndex":315,"id":"exchange-137"},{"speaker":"土井委員","kind":"意見","question":"今の事例でいけば、７９ページのところには、諸収入というスタイルで、その他の中身が記載されているんだと思いますし、６３ページの繰入金という形で、その他の特定財源についてのあれが書いてあるんだと思うんです。それから、特定財源と言っているもののその他って何だということが、どうも今まで論議された気がしないんです、あまり。では、次に移ります。そういうのがどうなっているのかなと。","respondent":"榎本人事課長","answer":"各戸収集につきましては、かなり努力してやっているという形は聞いておりますけれども、その部分と、そうでない部分の切り分けを、今後どうしていくかということは検討していかざるを得ないのかなと考えています。","voiceIndex":318,"id":"exchange-138"},{"speaker":"土井委員","kind":"質問","question":"そうしないと、この路地をやってくれというときにできないんです。日がわりのアルバイトじゃ、できっこないんですよ。そういう問題もありますから、やはりちゃんとした人をつくっていかなきゃいけないと思うので、何かほかのところに比べて減率が大き過ぎるように見えてしようがないものですから、ちょっとお伺いさせていただいたので、その辺の考え方を、ちょっとお聞かせください。","respondent":"島袋品川区清掃事務所長","answer":"個別収集については、職員の工夫と、車の増員とか、これらのことでやっておりまして、先ほど、人事課長が答えましたように、これから退職不補充だとしても、どこかの部分をどう工夫するか、あるいは中で工夫するか、資源とかほかのリサイクルの組み合わせをどうするかとか。","voiceIndex":320,"id":"exchange-139"},{"speaker":"土井委員","kind":"質問・要望","question":"仕事はしなきゃいけない、必ず取ってこなきゃいけないんです。ですから、それをきちんとやっていくために必要な人員と、それがどういうメンバーでやるかということは、やっぱりきちっとしておかなきゃいけないと思うんですよ。ところが、アルバイトみたいな人が毎日日がわりじゃどうにもならないんだと思いますよ、そういう仕事は。お願いをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":322,"id":"exchange-140"},{"speaker":"須藤委員","kind":"質問・要望","question":"各ページに出てきます、職員給与追加分と、最後の９７ページに出てくる非常勤職員、それから、一般職員の給与のことについて、お尋ねいたします。私の足し算が違うのか、教えていただきたい。それから、職員の手当等がいろいろついていますけれども、これは２３区同一になっているのか、どうか教えてください。","respondent":"日下部企画財政課長、市岡区議会事務局長、榎本人事課長","answer":"私のほうから１点目のご質問にお答えいたします。当然、新年度の当初予算は、給与明細書の４０名になっているというものです。職員手当が２３区同一かということですが、ここに出ている中では、特殊勤務手当を除き、２３区同一です。特殊勤務手当は各区で設定をしたものです。","voiceIndex":324,"id":"exchange-141"},{"speaker":"須藤委員","kind":"質問","question":"最初のほうの質問なんですけれども、例えば、６０ページの議会費では、この旅費は違いますが、そのほかの総務費のほうでは、やはり旅費というのが入ってきていますよね。それと同時に、非常勤の職員が３,５６１人となっていますよね。そうすると、事業について云々というのは、職員と事業とかというのはつかみにくいという話でいいですか。","respondent":"日下部企画財政課長","answer":"平成１７年からこういう形で、款別といいますか、切り分けをするようになりました。今申し上げたような点が、旅費にかかわる分だけはちょっと違ってまいりますけれども、例えば、今回で申しますと、これが２４７万円ほどのマイナスということになってまいります。","voiceIndex":328,"id":"exchange-142"},{"speaker":"須藤委員","kind":"質問・要望","question":"このあたりはどういうふうになっているのか、教えていただきたい。期末手当というのは、ある程度勤勉にやっているとか、云々というのを足してやるんだけれども、期末手当も優秀である、それから、また優秀であるというふうに見ていくのか、そのあたりを教えていただきたい。それから、初任給調整費というのは、ちょっと何だかわからないんですけれども、どういうことなんだか、教えていただきたいと思います。","respondent":"榎本人事課長","answer":"特殊勤務手当は、各区それぞれ設定がありますけれども、この中で、区独自のものでいきますと、特殊勤務手当は２３区それぞれが設定をして、各区で必要に応じて設定をして、つけている手当です。","voiceIndex":330,"id":"exchange-143"},{"speaker":"須藤委員","kind":"意見","question":"やはり、職員が一生懸命やっていて、２３区地方自治体は独自でいこうという時期にあって、この手当の出し方も２３区一緒なのかどうか、その辺も聞きたいんですけれども、もう時間がないからあれだけれども、やはり一生懸命やっていることで評価するような仕組みをつくっていってもらえたらいいと思うので、また、今後にします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":332,"id":"exchange-144"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、８３ページの目黒川親水護岸整備工事について、幾つかご説明いただきたいと思います。補正の理由ですけれども、護岸整備工事委託の減額と、護岸整備工事積算業務委託の増額がありますけれども、それぞれ補正の理由をご説明いただけますか。","respondent":"青木都市開発課長","answer":"目黒川護岸の整備工事に関するご質問ということで、工事の委託につきましては、今、現在施工中でございまして、平成１９年度の出来高を確認したところ、当初予定したものより少ないということで減額しているものです。","voiceIndex":334,"id":"exchange-145"},{"speaker":"中塚委員","kind":"質問・要望","question":"出来高というところと、見直しというのがよくわからなかったので、もうちょっとご説明いただきたい。それから、補正後も、総工事委託費は同額ですけれども、改めて国の補助金が幾らか、それから区の一般財源から出ているものは幾らか、ご説明いただけますか。","respondent":"青木都市開発課長","answer":"現在、このうち、国からの補助金を申請しておりますのが１億９,８００万円ほどを予定しておりまして、残額については、区の一般財源からの負担になります。","voiceIndex":336,"id":"exchange-146"},{"speaker":"中塚委員","kind":"質問","question":"僕の聞き方がまずかったのか、総工事委託費の中で、国から来るお金が幾らか、その差し引きで、区の一般財源から出てくるものは幾らか、それを教えていただけますか。","respondent":"青木都市開発課長","answer":"失礼いたしました。補助対象費が１億９,８００万円で、これの３分の１が国庫補助に当たりますので、現在、予定しておりますのは６,６００万円ということになります。","voiceIndex":338,"id":"exchange-147"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のご説明ですと、国からは６,６００万円ということですかね。区からは、とりあえず約３億２,０００万円ということですけれども、目黒川の護岸の整備というのは、本来はどこがやるべきことなのか、それを教えていただきたい。なぜ、区の一般財源から、これだけの３億円余りのお金が出るのか、教えていただけますか。","respondent":"青木都市開発課長","answer":"この護岸の整備ですけれども、ちょっと先ほど申し上げましたが、その護岸の裏側で、現在、市街地再開発事業が施工されておりまして、そこの再開発事業において、その護岸に隣接する敷地を公園として整備していただいて。","voiceIndex":340,"id":"exchange-148"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、本来、目黒川の護岸というのはだれが整備するものなのかということです。後半の説明の中で、開発事業者と言ったらいいんでしょうか、そこから幾らか返ってくると言いますけれども、じゃあ、その結果区の負担はゼロになるのか、教えていただけますか。","respondent":"青木都市開発課長、日下部企画財政課長","answer":"場合によっては、さらなる管理、運営とか、そういったところにも、地元の方々のご参画が得られるものと、私どもはそういったものを目指して、現在、まちづくりを進めているところです。財源の問題ですけれども、都市再生総合整備事業ということでありまして、さっき、都市開発課長のほうからご説明させていただきました。対象の３分の１は国からまいります。","voiceIndex":342,"id":"exchange-149"},{"speaker":"中塚委員","kind":"質問","question":"どうしてもよくわからないのが、本来、河川管理者であります東京都が護岸をやるのに、最終的な負担は、今はまだはっきりしない、できるだけ小さくというお話ですけれども、なぜ区が負担することになるのか、ここがよくわからないところなんです。逆に、補助対象にならないものは幾らになるのか。それぞれ工事の内容も違うと思うんですけれども、教えていただけますか。","respondent":"青木都市開発課長","answer":"先ほどちょっと申し上げましたが、その２億５,０００万円弱の約８割を見込んで国に申請しておりまして、補助対象額を１億９,８００万円と見込んで、６,６００万円補助金が欲しいということで申請しているものです。","voiceIndex":345,"id":"exchange-150"},{"speaker":"中塚委員","kind":"質問","question":"補助対象になるものが２億５,０００万円で、そのうちの８割という話ですけれども、ということは、補助対象にならないものもあるわけですよね。要は、区としては必要だと思うけれども、国からは補助対象にならない事業が、この中に工事としては含まれているわけですね。そこがよくわからないんです。本来であるなら、護岸は東京都がやるのに、なぜ区がやるのか、そこを教えていただけますか。","respondent":"岩田まちづくり事業部長","answer":"それに対して３分の１を国庫補助で見込んでいる。残りの３分の２を、一応財調で考えている。では、２億円以上の１億７,８００万円相当、補助対象外については、地元の寄附というもので、全額品川区の一般財源を投入しないで事業を展開するです。","voiceIndex":347,"id":"exchange-151"},{"speaker":"中塚委員","kind":"質問","question":"総務委員会の議事録を見てみましたら、いわゆる護岸というのは非常に丈夫にできているもので、耐久年数は長いわけですよね。ここをつくられたのが昭和６１年と書いてありましたが、まだ２０年ちょっとしか経ってないわけですね。それをなぜ、わざわざ壊して新設するのかというところなんですよね。逆に、そこを区が負担をする。違いがあるんであれば、どういう違いなのか、教えていただけますか。","respondent":"青木都市開発課長","answer":"国の理屈も理解できますし、私ども自治体の考え方としてまちづくりを進めていく上で必要な工事であるということで、国の補助があるかないかにかかわらず進めていく必要があるという点については、ぜひご理解いただきたいと考えています。","voiceIndex":349,"id":"exchange-152"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話、国と区と、それぞれの考え方のご説明があったわけですけれども、その中で、区の政策の変化に伴うものというお話がありましたけれども、どういう変化なのか、教えていただきたい。護岸というのは、本来どれぐらい長くもつものなのかわからないですけれども、大体一般的に、目黒川の護岸というのは耐久年数はあとどれぐらい残っているものなんですか。年数で、ちょっと教えてください。","respondent":"岩田まちづくり事業部長","answer":"したがって、私どもの長期計画の中でも、やはりできるところから水辺に親しめるような環境整備をしていきましょうと、こういう計画の一環として、ここでは、民の力を借りながら事業を進めていると、こういうことです。","voiceIndex":351,"id":"exchange-153"},{"speaker":"中塚委員","kind":"質問","question":"今後、どういうふうにそこを売り出すのか、広告はまだ出ていませんからわかりませんけれども、なぜこれが必要なのかと思うと、もしかしたら区は意図していないと言いたいのかもしないけれども、結局はそこの開発の質やレベルを上げることになる。工事を見ていますと、どう見てもそう見えるんですよね。その辺は、一体どういうふうに今、見ているのか。最後に教えてください。","respondent":"岩田まちづくり事業部長","answer":"公園等の公共施設を行政がそこにつくりました。その隣近所にある地権者が、その公園をどのように商売にＰＲしようと、それは行政の知らぬところです。","voiceIndex":353,"id":"exchange-154"},{"speaker":"三上委員","kind":"質問・要望","question":"品川荘が改築されるときにも、高架槽をなくして、増圧ということで圧力をかけて最上階まで持っていけるようにという方法を取り入れたらどうかということも言ってありますし、平成９年の第１回定例会の一般質問で、私は、水道水を遮断できるような形から、緊急貯水槽というか、小規模貯水槽、これを少なくともの敷地内に導入したらどうでしょうかと。そういう状況が今でも続いてきているのか。","respondent":"浜脇街路事業担当課長、市川庶務課長","answer":"７７ページの目黒線の関係ですけれども、これにつきましては、今、平成２０年度の再伸に向けて努力しておりますけれども、一部、工事の進捗によりまして、執行率が若干変わって、平成１９年度の清算が。ただ、推測するところ、先ほど、午前中の説明のときに申し上げましたが、学校の配管設備の設備更新の時期と外壁工事との関係で、要するにその辺の経済性というものを考慮しながら検討させていただきたいと。","voiceIndex":356,"id":"exchange-155"},{"speaker":"三上委員","kind":"質問","question":"その次の、何か平成１９年度がどうのこうのというのが聞き取れなくて、これはまた後ほど伺っていこうと考えています。それから、水道管の関係に関して、今回、大井第一小学校が、外壁だとか、学校の設備だとかということで取り組むということですが、ほかの学校で、新築する学校も含めて、こういうような取り組み方をしたというところはあるんですか。","respondent":"市川庶務課長","answer":"東京都のほうで、平成１９年度と２０年度の事業ということで打ち出した関係もありますので、私のほうとしては、今後の校舎改築の中でどう取り組むか、この辺はひとつ課題として考えております。","voiceIndex":359,"id":"exchange-156"},{"speaker":"三上委員","kind":"質問","question":"水道局としては、せっかくおいしい水をつくっているんだから、それを積極的に使ってくれということになってきているわけですから、それでまた増圧をすれば、そのおいしい水も、通常の感覚では、今は、高架槽の上にタンクがなくても送れますという仕組みになってきている時代にあって、やっと東京都がこの平成１９年度、２０年度で特別に予算をつけるからやれということだと思います。","respondent":"日下部企画財政課長","answer":"今回はモデルとして、東京都もお金を出してくれましたけれども、その辺の負担の問題でありますとか、あるいは施設によって、３階までの水圧の問題、施設すべてが対象になるわけではないと、そういう課題も含めて検討していかなければいけないのではないかと。","voiceIndex":361,"id":"exchange-157"},{"speaker":"三上委員","kind":"質問・要望","question":"最後にお願いしておきます。高架槽に入れた水だって、水道料金はかかっているはずですよ。それを、流さなければならないというむだに使っている水もあるということはわかっているわけですから、そういったことを考えた上での水道の考え方を、しっかり取り組んでいっていただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":363,"id":"exchange-158"},{"speaker":"林委員","kind":"質問","question":"１００ページ以降に出てくる債務負担行為、それから、６１ページ、３カ所ですか、基金の積立、そういったことで、財政的な考え方をお聞かせください。いろいろな形があるんですけれども、こうやって金利が高くなってくると、例えば、ここには出ていないですけれども、リサイクルの基金だとか、一応は１億円とか、２億円とか決められているんだけれども、増やしてもいいというようなことを条例でうたっている。","respondent":"市川庶務課長、日下部企画財政課長","answer":"工事といたしましては、夏休み工事で対応していますけれども、東京都のほうの助成内容が、当初は、原材料費相当ということになっておりましたけれども、それが、最終的には、今回計上しておりますけれども。２点目の基金の関係です。","voiceIndex":365,"id":"exchange-159"},{"speaker":"林委員","kind":"質問","question":"そうじゃなくて、だから、区債に頼るというか、区債という手法で後年度負担という、おしなべてみんなで負担をしてもらうという考え方、債務負担と同じでしょと言って、その線引きは何か決まりがあるんですかと聞いているわけです。昨年の秋というのは、平成１９年の秋、昨年度じゃなくて、平成１９年秋ということですか。それはなぜなんですか。それはそれでわかる。だから、基金をどういうふうに扱うか。","respondent":"日下部企画財政課長","answer":"起債と債務負担のほう、なかなかこれは難しいご質問なんですが、起債の場合の一つの線引きということになりますと、債務負担行為というのは、完全に会計年度独立の原則の一つの例外ということで、事業を数カ年にわたって実施するような場合、あるいは。","voiceIndex":368,"id":"exchange-160"},{"speaker":"林委員","kind":"質問","question":"債務は両方債務なんですよ。もう工事を始めて、このお金は２年半後、完成したときに払わなければいけない。さっき言ったように、借金という考え方もできるわけですから、そういった意味で、これからいわゆる企業会計を入れていくと、一般質問の中でもありましたけれども、はっきりしたそういう考え方を持って、いろいろな処理をしていかなきゃいけないのかなと思う。それだけ最後に教えてください。","respondent":"日下部企画財政課長","answer":"区の予算上、引当金というものは、どこにも出てまいりません。ここで、経営状況の中で出しております金額というのは、これは民間と同じだと思いますが、年度末に、今、在籍している職員が全員退職した場合を仮定しまして、その金額をこちらに計上しているというものです。","voiceIndex":370,"id":"exchange-161"},{"speaker":"林委員","kind":"意見","question":"ということは、さっき言ったけれども、私企業では内部留保なんですよ、引当金というのは。それが３００億円近い数字が出ているんだけれども、これは、いわゆる架空の数字、実際に内部留保されているとか、そういうものじゃないと理解しておいていいんですね。わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":372,"id":"exchange-162"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=892#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":125934,"voices":376}}]);
